# =========================================================
# JUSTMUSIC! 6.0.2 — BEÁGYAZOTT PARTY WALLPAPER
# =========================================================
# Ez PONTOSAN a kiválasztott PNG, közvetlenül a .py fájlba
# base64-ként beágyazva. Nem kell mellé külön képfájl.
JM_PARTY_BACKGROUND_B64 = """"""

JM_PARTY_BG_BRIGHTNESS = 0.58
JM_PARTY_BG_SATURATION = 1.05
JM_PARTY_BG_BLUR = 1.2

_jm_party_source_cache = None
_jm_party_bg_states = {}


def _jm_party_source():
    global _jm_party_source_cache

    if _jm_party_source_cache is not None:
        return _jm_party_source_cache

    if Image is None:
        return None

    try:
        raw = base64.b64decode(
            JM_PARTY_BACKGROUND_B64
        )

        image = Image.open(
            io.BytesIO(raw)
        ).convert(
            "RGB"
        )

        _jm_party_source_cache = image
        return image

    except Exception as error:
        print(
            "PARTY HÁTTÉR BETÖLTÉSI HIBA:",
            error
        )
        return None


def _jm_make_party_photo(
    width,
    height,
    brightness=None,
    blur=None,
    saturation=None,
):
    source = _jm_party_source()

    if (
        source is None
        or ImageTk is None
        or ImageOps is None
    ):
        # Fallback: legalább az eredeti PNG jelenjen meg.
        try:
            return tk.PhotoImage(
                data=JM_PARTY_BACKGROUND_B64
            )
        except Exception:
            return None

    width = max(
        2,
        int(width)
    )

    height = max(
        2,
        int(height)
    )

    if brightness is None:
        brightness = JM_PARTY_BG_BRIGHTNESS

    if blur is None:
        blur = JM_PARTY_BG_BLUR

    if saturation is None:
        saturation = JM_PARTY_BG_SATURATION

    try:
        if hasattr(
            Image,
            "Resampling"
        ):
            resize_filter = Image.Resampling.LANCZOS
        else:
            resize_filter = getattr(
                Image,
                "LANCZOS",
                Image.BICUBIC
            )

        image = ImageOps.fit(
            source,
            (
                width,
                height
            ),
            method=resize_filter
        )

        if ImageEnhance is not None:
            image = ImageEnhance.Brightness(
                image
            ).enhance(
                float(brightness)
            )

            image = ImageEnhance.Color(
                image
            ).enhance(
                float(saturation)
            )

        if (
            ImageFilter is not None
            and blur
            and float(blur) > 0
        ):
            image = image.filter(
                ImageFilter.GaussianBlur(
                    radius=float(blur)
                )
            )

        return ImageTk.PhotoImage(
            image
        )

    except Exception as error:
        print(
            "PARTY HÁTTÉR RENDER HIBA:",
            error
        )
        return None


def install_party_background(
    container,
    brightness=None,
    blur=None,
    saturation=None,
):
    """Skálázott party háttér egy Tkinter konténer mögé."""
    if (
        Image is None
        or ImageTk is None
    ):
        return None

    try:
        label = tk.Label(
            container,
            bg=JM_BG,
            borderwidth=0,
            highlightthickness=0
        )

        label._jm_party_bg = True

        label.place(
            x=0,
            y=0,
            relwidth=1,
            relheight=1
        )

        label.lower()

        state = {
            "label": label,
            "photo": None,
            "after": None,
            "brightness": brightness,
            "blur": blur,
            "saturation": saturation,
        }

        _jm_party_bg_states[
            str(container)
        ] = state

        def render_now():
            state["after"] = None

            try:
                if not label.winfo_exists():
                    return

                width = max(
                    2,
                    container.winfo_width()
                )

                height = max(
                    2,
                    container.winfo_height()
                )

                photo = _jm_make_party_photo(
                    width,
                    height,
                    brightness=state["brightness"],
                    blur=state["blur"],
                    saturation=state["saturation"],
                )

                if photo is None:
                    return

                state["photo"] = photo

                label.config(
                    image=photo
                )

                label.lower()

            except Exception:
                pass

        def schedule_render(event=None):
            try:
                if state["after"] is not None:
                    container.after_cancel(
                        state["after"]
                    )
            except Exception:
                pass

            try:
                state["after"] = container.after(
                    120,
                    render_now
                )
            except Exception:
                pass

        container.bind(
            "<Configure>",
            schedule_render,
            add="+"
        )

        container.after_idle(
            render_now
        )

        return label

    except Exception as error:
        print(
            "PARTY HÁTTÉR TELEPÍTÉSI HIBA:",
            error
        )
        return None




def install_party_canvas_background(
    canvas_widget,
    brightness=0.56,
    blur=1.5,
    saturation=1.04,
):
    """
    Valódi háttérkép egy Canvas SAJÁT háttereként.
    Ez azért kell, mert a Canvas maga különben eltakarja
    a mögötte levő root / frame wallpaper-t.
    """
    state = {
        "photo": None,
        "image_id": None,
        "after": None,
    }

    def render_now():
        state["after"] = None

        try:
            if not canvas_widget.winfo_exists():
                return

            width = max(
                2,
                canvas_widget.winfo_width()
            )
            height = max(
                2,
                canvas_widget.winfo_height()
            )

            photo = _jm_make_party_photo(
                width,
                height,
                brightness=brightness,
                blur=blur,
                saturation=saturation,
            )

            if photo is None:
                return

            state["photo"] = photo

            if state["image_id"] is None:
                state["image_id"] = canvas_widget.create_image(
                    0,
                    0,
                    anchor="nw",
                    image=photo,
                    tags=("jm_party_canvas_bg",)
                )
            else:
                canvas_widget.itemconfig(
                    state["image_id"],
                    image=photo
                )

            canvas_widget.coords(
                state["image_id"],
                0,
                0
            )

            canvas_widget.tag_lower(
                state["image_id"]
            )

        except Exception as error:
            print(
                "CANVAS PARTY HÁTTÉR HIBA:",
                error
            )

    def schedule(event=None):
        try:
            if state["after"] is not None:
                canvas_widget.after_cancel(
                    state["after"]
                )
        except Exception:
            pass

        try:
            state["after"] = canvas_widget.after(
                100,
                render_now
            )
        except Exception:
            pass

    canvas_widget.bind(
        "<Configure>",
        schedule,
        add="+"
    )

    canvas_widget.after_idle(
        render_now
    )

    return state


def install_party_everywhere(
    widget,
    brightness=0.34,
    blur=3.0,
    saturation=0.94,
):
    """
    Gyors helper Frame / Label jellegű konténerekhez.
    A háttér sötét marad, de a buli-kép minden fő részen átjön.
    """
    try:
        return install_party_background(
            widget,
            brightness=brightness,
            blur=blur,
            saturation=saturation
        )
    except Exception:
        return None


