def _safe_filename(name):
    """Windows-kompatibilis fájlnevet készít."""
    name = str(name or "").strip()

    # Windowsban tiltott karakterek.
    name = re.sub(
        r'[<>:"/\\|?*]+',
        "_",
        name
    )

    # Ne legyen ponttal vagy szóközzel a végén.
    name = name.strip(" .")

    if not name:
        name = "letoltott_zene"

    return name


def _unique_download_path(filename):
    """
    Egyedi mentési útvonal a MUSIC_FOLDER mappába.
    Ha már létezik a fájl, pl.:
    Dal.mp3 -> Dal (1).mp3 -> Dal (2).mp3
    """
    os.makedirs(
        MUSIC_FOLDER,
        exist_ok=True
    )

    filename = _safe_filename(
        filename
    )

    base, ext = os.path.splitext(
        filename
    )

    if not ext:
        ext = ".mp3"

    path = os.path.join(
        MUSIC_FOLDER,
        base + ext
    )

    counter = 1

    while os.path.exists(path):
        path = os.path.join(
            MUSIC_FOLDER,
            f"{base} ({counter}){ext}"
        )
        counter += 1

    return path


def _filename_from_response(url, response):
    """Fájlnevet próbál kinyerni a HTTP válaszból vagy az URL-ből."""
    disposition = str(
        response.headers.get(
            "Content-Disposition",
            ""
        )
    )

    match = re.search(
        r'filename\*?=(?:UTF-8\'\')?["\']?([^"\';]+)',
        disposition,
        flags=re.IGNORECASE
    )

    if match:
        filename = urllib.parse.unquote(
            match.group(1).strip()
        )

        if filename:
            return os.path.basename(
                filename
            )

    parsed = urllib.parse.urlparse(
        url
    )

    filename = os.path.basename(
        parsed.path
    )

    filename = urllib.parse.unquote(
        filename
    )

    if filename:
        return filename

    return "letoltott_zene.mp3"


def _looks_like_audio(filename, content_type):
    """Megnézi, hogy a válasz valószínűleg támogatott hangfájl-e."""
    ext = os.path.splitext(
        str(filename or "")
    )[1].lower()

    if ext in SUPPORTED_AUDIO:
        return True

    content_type = str(
        content_type or ""
    ).lower()

    return content_type.startswith(
        "audio/"
    )



