# =========================================================
# HALLGATASI ELOZMENYEK / STATISZTIKAK
# =========================================================

def _default_track_stats():
    return {
        "play_count": 0,
        "listened_seconds": 0.0,
        "last_played": None,
    }


def load_stats():
    global listening_stats
    global listening_history

    listening_stats = {}
    listening_history = []

    try:
        if not os.path.isfile(
            STATS_FILE
        ):
            return

        with open(
            STATS_FILE,
            "r",
            encoding="utf-8"
        ) as file:
            data = json.load(
                file
            )

        if not isinstance(
            data,
            dict
        ):
            return

        raw_stats = data.get(
            "tracks",
            {}
        )

        if isinstance(
            raw_stats,
            dict
        ):
            for path, item in raw_stats.items():
                if not isinstance(
                    item,
                    dict
                ):
                    continue

                listening_stats[str(path)] = {
                    "play_count": int(
                        item.get(
                            "play_count",
                            0
                        )
                        or 0
                    ),
                    "listened_seconds": float(
                        item.get(
                            "listened_seconds",
                            0.0
                        )
                        or 0.0
                    ),
                    "last_played": item.get(
                        "last_played"
                    ),
                }

        raw_history = data.get(
            "history",
            []
        )

        if isinstance(
            raw_history,
            list
        ):
            listening_history = [
                item
                for item in raw_history
                if isinstance(
                    item,
                    dict
                )
                and item.get(
                    "path"
                )
            ][-500:]

    except Exception as error:
        print(
            "STATISZTIKA BETÖLTÉSI HIBA:",
            error
        )


def save_stats():
    global stats_save_after_id

    stats_save_after_id = None

    try:
        os.makedirs(
            MUSIC_FOLDER,
            exist_ok=True
        )

        temp_path = (
            STATS_FILE
            + ".tmp"
        )

        with open(
            temp_path,
            "w",
            encoding="utf-8"
        ) as file:
            json.dump(
                {
                    "version": 1,
                    "tracks": listening_stats,
                    "history": listening_history[-500:],
                },
                file,
                ensure_ascii=False,
                indent=2
            )

        os.replace(
            temp_path,
            STATS_FILE
        )

    except Exception as error:
        print(
            "STATISZTIKA MENTÉSI HIBA:",
            error
        )


def schedule_save_stats():
    global stats_save_after_id

    try:
        if stats_save_after_id is not None:
            root.after_cancel(
                stats_save_after_id
            )
    except Exception:
        pass

    try:
        stats_save_after_id = root.after(
            3000,
            save_stats
        )
    except Exception:
        stats_save_after_id = None


def track_by_path(path):
    for track in library:
        if track.get(
            "path"
        ) == path:
            return track

    return None


def register_track_start(
    track,
    start_position=0.0
):
    """
    Lejátszásnak akkor számítjuk, ha kb. a dal elejéről indul.
    A 10 mp-es debounce megakadályozza, hogy EQ újrafeldolgozás
    vagy gyors újraindítás duplán számoljon.
    """
    global stats_last_count_path
    global stats_last_count_time
    global stats_last_track_path
    global stats_last_tick

    if track is None:
        return

    path = str(
        track.get("path")
        or ""
    )

    if not path:
        return

    stats_last_track_path = path
    stats_last_tick = time.perf_counter()

    try:
        start_position = float(
            start_position
        )
    except Exception:
        start_position = 0.0

    if start_position > 1.5:
        return

    now_perf = time.perf_counter()

    if (
        stats_last_count_path == path
        and (
            now_perf
            - stats_last_count_time
        ) < 10.0
    ):
        return

    stats_last_count_path = path
    stats_last_count_time = now_perf

    item = listening_stats.setdefault(
        path,
        _default_track_stats()
    )

    item["play_count"] = int(
        item.get(
            "play_count",
            0
        )
    ) + 1

    now_iso = datetime.now().isoformat(
        timespec="seconds"
    )

    item["last_played"] = now_iso

    listening_history.append(
        {
            "path": path,
            "title": track.get(
                "title",
                ""
            ),
            "artist": track.get(
                "artist",
                ""
            ),
            "album": track.get(
                "album",
                ""
            ),
            "played_at": now_iso,
        }
    )

    del listening_history[:-500]

    schedule_save_stats()


def tick_listening_stats():
    global stats_last_tick
    global stats_last_track_path

    now = time.perf_counter()

    track = current_track()

    if (
        not song_started
        or paused
        or track is None
    ):
        stats_last_tick = now

        stats_last_track_path = (
            track.get("path")
            if track
            else None
        )

        return

    path = str(
        track.get("path")
        or ""
    )

    if not path:
        stats_last_tick = now
        return

    if (
        stats_last_tick is None
        or stats_last_track_path != path
    ):
        stats_last_tick = now
        stats_last_track_path = path
        return

    delta = (
        now - stats_last_tick
    )

    stats_last_tick = now

    if (
        delta <= 0
        or delta > 2.0
    ):
        return

    item = listening_stats.setdefault(
        path,
        _default_track_stats()
    )

    item["listened_seconds"] = float(
        item.get(
            "listened_seconds",
            0.0
        )
    ) + delta


def format_long_time(seconds):
    seconds = int(
        max(
            0,
            seconds
        )
    )

    hours = seconds // 3600
    minutes = (
        seconds % 3600
    ) // 60

    if hours > 0:
        return f"{hours} ó {minutes} p"

    if minutes > 0:
        return f"{minutes} perc"

    return f"{seconds} mp"


def _stats_track_rows():
    rows = []

    for path, item in listening_stats.items():
        track = track_by_path(
            path
        )

        if track is None:
            continue

        rows.append(
            (
                track,
                int(
                    item.get(
                        "play_count",
                        0
                    )
                ),
                float(
                    item.get(
                        "listened_seconds",
                        0.0
                    )
                ),
                item.get(
                    "last_played"
                ),
            )
        )

    return rows


def clear_listening_history():
    global listening_stats
    global listening_history

    answer = messagebox.askyesno(
        "JustMusic! - Statisztikák",
        (
            "Biztosan törlöd az összes hallgatási előzményt "
            "és statisztikát?"
        ),
        parent=root
    )

    if not answer:
        return

    listening_stats = {}
    listening_history = []

    save_stats()
    show_stats()


