# =========================================================
# BEALLITASOK MENTESE / BETOLTESE
# =========================================================

def _collect_settings():
    geometry = saved_window_geometry

    try:
        if (
            "root" in globals()
            and root.winfo_exists()
        ):
            geometry = root.geometry()
    except Exception:
        pass

    return {
        "version": 1,
        "volume_percent": float(
            saved_volume_percent
        ),
        "window_geometry": geometry,

        "shuffle_enabled": bool(
            shuffle_enabled
        ),
        "repeat_mode": str(
            repeat_mode
        ),

        "mixer": {
            "crossfade_enabled": bool(
                crossfade_enabled
            ),
            "fade_out_seconds": float(
                mix_fade_out_seconds
            ),
            "fade_in_seconds": float(
                mix_fade_in_seconds
            ),
            "auto_transition": bool(
                mix_auto_transition_enabled
            ),
            "manual_transition": bool(
                mix_manual_transition_enabled
            ),
            "gapless": bool(
                mix_gapless_enabled
            ),
            "dj_mode": bool(
                mix_dj_mode_enabled
            ),
        },

        "loudness": {
            "enabled": bool(
                normalization_enabled
            ),
            "target_lufs": float(
                normalization_target_lufs
            ),
            "true_peak": float(
                normalization_true_peak
            ),
        },

        "equalizer": {
            "enabled": bool(
                eq_enabled
            ),
            "preamp_db": float(
                eq_preamp_db
            ),
            "bands": {
                str(frequency): float(
                    eq_band_values.get(
                        frequency,
                        0.0
                    )
                )
                for frequency, _ in EQ_BANDS
            },
        },
    }


def save_settings():
    global settings_save_after_id
    global saved_window_geometry

    settings_save_after_id = None

    if settings_loading:
        return

    try:
        os.makedirs(
            MUSIC_FOLDER,
            exist_ok=True
        )

        data = _collect_settings()

        saved_window_geometry = str(
            data.get(
                "window_geometry",
                saved_window_geometry
            )
        )

        temp_path = (
            SETTINGS_FILE
            + ".tmp"
        )

        with open(
            temp_path,
            "w",
            encoding="utf-8"
        ) as file:
            json.dump(
                data,
                file,
                ensure_ascii=False,
                indent=2
            )

        os.replace(
            temp_path,
            SETTINGS_FILE
        )

    except Exception as error:
        print(
            "BEÁLLÍTÁS MENTÉSI HIBA:",
            error
        )


def schedule_save_settings():
    global settings_save_after_id

    if settings_loading:
        return

    try:
        if settings_save_after_id is not None:
            root.after_cancel(
                settings_save_after_id
            )
    except Exception:
        pass

    try:
        settings_save_after_id = root.after(
            350,
            save_settings
        )
    except Exception:
        # Ha a root még nem létezik, majd később mentjük.
        settings_save_after_id = None


def load_settings():
    global settings_loading
    global saved_volume_percent
    global saved_window_geometry

    global shuffle_enabled
    global repeat_mode

    global crossfade_enabled
    global mix_fade_out_seconds
    global mix_fade_in_seconds
    global mix_auto_transition_enabled
    global mix_manual_transition_enabled
    global mix_gapless_enabled
    global mix_dj_mode_enabled

    global eq_enabled
    global eq_preamp_db

    global normalization_enabled
    global normalization_target_lufs
    global normalization_true_peak

    settings_loading = True

    try:
        if not os.path.isfile(
            SETTINGS_FILE
        ):
            return

        with open(
            SETTINGS_FILE,
            "r",
            encoding="utf-8"
        ) as file:
            data = json.load(
                file
            )

        if not isinstance(
            data,
            dict
        ):
            return

        try:
            saved_volume_percent = max(
                0.0,
                min(
                    100.0,
                    float(
                        data.get(
                            "volume_percent",
                            80.0
                        )
                    )
                )
            )
        except Exception:
            saved_volume_percent = 80.0

        geometry = str(
            data.get(
                "window_geometry",
                "1280x820"
            )
            or "1280x820"
        ).strip()

        if "x" in geometry:
            saved_window_geometry = geometry

        shuffle_enabled = bool(
            data.get(
                "shuffle_enabled",
                False
            )
        )

        loaded_repeat = str(
            data.get(
                "repeat_mode",
                "off"
            )
        ).lower()

        repeat_mode = (
            loaded_repeat
            if loaded_repeat in (
                "off",
                "all",
                "one"
            )
            else "off"
        )

        mixer = data.get(
            "mixer",
            {}
        )

        if isinstance(
            mixer,
            dict
        ):
            crossfade_enabled = bool(
                mixer.get(
                    "crossfade_enabled",
                    False
                )
            )

            try:
                mix_fade_out_seconds = max(
                    0.0,
                    min(
                        10.0,
                        float(
                            mixer.get(
                                "fade_out_seconds",
                                1.5
                            )
                        )
                    )
                )
            except Exception:
                mix_fade_out_seconds = 1.5

            try:
                mix_fade_in_seconds = max(
                    0.0,
                    min(
                        10.0,
                        float(
                            mixer.get(
                                "fade_in_seconds",
                                1.5
                            )
                        )
                    )
                )
            except Exception:
                mix_fade_in_seconds = 1.5

            mix_auto_transition_enabled = bool(
                mixer.get(
                    "auto_transition",
                    True
                )
            )

            mix_manual_transition_enabled = bool(
                mixer.get(
                    "manual_transition",
                    True
                )
            )

            mix_gapless_enabled = bool(
                mixer.get(
                    "gapless",
                    False
                )
            )

            mix_dj_mode_enabled = bool(
                mixer.get(
                    "dj_mode",
                    False
                )
            )

            # Gapless és crossfade ne legyen egyszerre aktív.
            if mix_gapless_enabled:
                crossfade_enabled = False

        loudness = data.get(
            "loudness",
            {}
        )

        if isinstance(
            loudness,
            dict
        ):
            normalization_enabled = bool(
                loudness.get(
                    "enabled",
                    False
                )
            )

            try:
                normalization_target_lufs = max(
                    -23.0,
                    min(
                        -8.0,
                        float(
                            loudness.get(
                                "target_lufs",
                                -14.0
                            )
                        )
                    )
                )
            except Exception:
                normalization_target_lufs = -14.0

            try:
                normalization_true_peak = max(
                    -3.0,
                    min(
                        -0.5,
                        float(
                            loudness.get(
                                "true_peak",
                                -1.5
                            )
                        )
                    )
                )
            except Exception:
                normalization_true_peak = -1.5

        equalizer = data.get(
            "equalizer",
            {}
        )

        if isinstance(
            equalizer,
            dict
        ):
            eq_enabled = bool(
                equalizer.get(
                    "enabled",
                    False
                )
            )

            try:
                eq_preamp_db = max(
                    -12.0,
                    min(
                        6.0,
                        float(
                            equalizer.get(
                                "preamp_db",
                                0.0
                            )
                        )
                    )
                )
            except Exception:
                eq_preamp_db = 0.0

            bands = equalizer.get(
                "bands",
                {}
            )

            if isinstance(
                bands,
                dict
            ):
                for frequency, _ in EQ_BANDS:
                    try:
                        eq_band_values[
                            frequency
                        ] = max(
                            -12.0,
                            min(
                                12.0,
                                float(
                                    bands.get(
                                        str(frequency),
                                        0.0
                                    )
                                )
                            )
                        )
                    except Exception:
                        eq_band_values[
                            frequency
                        ] = 0.0

    except Exception as error:
        print(
            "BEÁLLÍTÁS BETÖLTÉSI HIBA:",
            error
        )

    finally:
        settings_loading = False


def close_justmusic():
    global saved_window_geometry

    try:
        if (
            connect_window is not None
            and connect_window.winfo_exists()
        ):
            connect_window.destroy()
    except Exception:
        pass

    try:
        if (
            mini_player_window is not None
            and mini_player_window.winfo_exists()
        ):
            mini_player_window.destroy()
    except Exception:
        pass

    try:
        saved_window_geometry = root.geometry()
    except Exception:
        pass

    save_settings()
    save_stats()

    try:
        root.destroy()
    except Exception:
        pass




# =========================================================
# REPLAYGAIN-SZERU HANGEROKIEGYENLITES / LOUDNESS
# =========================================================

def update_loudness_ui():
    try:
        if loudness_button is not None:
            loudness_button.config(
                text=(
                    "RG"
                    if not normalization_enabled
                    else f"RG {normalization_target_lufs:.0f}"
                ),
                fg=(
                    JM_CYAN
                    if normalization_enabled
                    else JM_TEXT
                )
            )
    except Exception:
        pass

    try:
        if (
            loudness_status_label is not None
            and loudness_status_label.winfo_exists()
        ):
            if normalization_enabled:
                loudness_status_label.config(
                    text=(
                        "Hangerő-kiegyenlítés: BE  •  "
                        f"{normalization_target_lufs:.1f} LUFS  •  "
                        f"True Peak {normalization_true_peak:.1f} dBTP"
                    ),
                    fg=JM_CYAN
                )
            else:
                loudness_status_label.config(
                    text="Hangerő-kiegyenlítés: KI",
                    fg=JM_MUTED
                )
    except Exception:
        pass

    try:
        if (
            loudness_target_label is not None
            and loudness_target_label.winfo_exists()
        ):
            loudness_target_label.config(
                text=f"{normalization_target_lufs:.1f} LUFS"
            )
    except Exception:
        pass

    try:
        if (
            loudness_peak_label is not None
            and loudness_peak_label.winfo_exists()
        ):
            loudness_peak_label.config(
                text=f"{normalization_true_peak:.1f} dBTP"
            )
    except Exception:
        pass

    update_now_playing_progress()


def set_normalization_enabled(enabled):
    global normalization_enabled

    normalization_enabled = bool(
        enabled
    )

    update_loudness_ui()
    schedule_save_settings()


def toggle_normalization():
    set_normalization_enabled(
        not normalization_enabled
    )

    if current_track() is not None:
        apply_loudness_to_current()


def set_normalization_target(value):
    global normalization_target_lufs

    try:
        value = float(
            value
        )
    except Exception:
        value = -14.0

    normalization_target_lufs = max(
        -23.0,
        min(
            -8.0,
            value
        )
    )

    update_loudness_ui()
    schedule_save_settings()


def set_normalization_true_peak(value):
    global normalization_true_peak

    try:
        value = float(
            value
        )
    except Exception:
        value = -1.5

    normalization_true_peak = max(
        -3.0,
        min(
            -0.5,
            value
        )
    )

    update_loudness_ui()
    schedule_save_settings()


def apply_loudness_preset(name):
    preset = str(
        name
    ).lower()

    presets = {
        "streaming": (-14.0, -1.5),
        "balanced": (-16.0, -1.5),
        "night": (-18.0, -2.0),
        "loud": (-11.0, -1.0),
    }

    target, peak = presets.get(
        preset,
        (-14.0, -1.5)
    )

    set_normalization_target(
        target
    )

    set_normalization_true_peak(
        peak
    )

    set_normalization_enabled(
        True
    )

    apply_loudness_to_current()


def apply_loudness_to_current():
    track = current_track()

    if track is None:
        update_loudness_ui()
        return

    if (
        normalization_enabled
        and not _ffmpeg_path()
    ):
        messagebox.showerror(
            "JustMusic! - Hangerő-kiegyenlítés",
            (
                "Ehhez FFmpeg szükséges.\n\n"
                "Az FFmpeg már az EQ-hoz is kell."
            ),
            parent=root
        )
        return

    position = (
        get_current_position()
        if song_started
        else 0.0
    )

    was_paused = bool(
        paused
    )

    play_song(
        start_position=position,
        start_paused=was_paused
    )


