# =========================================================
# 10 SAVOS GRAPHIC EQUALIZER
# =========================================================

def _ffmpeg_path():
    return (
        shutil.which("ffmpeg")
        or shutil.which("ffmpeg.exe")
    )


def _eq_is_flat():
    return (
        abs(eq_preamp_db) < 0.05
        and all(
            abs(value) < 0.05
            for value in eq_band_values.values()
        )
    )


def _eq_filter_string():
    """
    Valódi 10 sávos FFmpeg EQ:
    31 / 62 / 125 / 250 / 500 Hz /
    1K / 2K / 4K / 8K / 16K Hz.
    """

    filters = []

    if abs(eq_preamp_db) >= 0.05:
        filters.append(
            f"volume={eq_preamp_db:.2f}dB"
        )

    for frequency, _ in EQ_BANDS:
        gain = float(
            eq_band_values.get(
                frequency,
                0.0
            )
        )

        if abs(gain) < 0.05:
            continue

        # A szélső sávok kicsit szélesebbek,
        # hogy zeneibb legyen az átmenet.
        if frequency <= 62:
            width = 0.80
        elif frequency >= 8000:
            width = 0.85
        else:
            width = 1.00

        filters.append(
            "equalizer="
            f"f={frequency}:"
            f"t=q:"
            f"w={width:.2f}:"
            f"g={gain:.2f}"
        )

    # Hangerő-kiegyenlítés az EQ UTÁN történik, így az EQ boost/cut
    # hatását is beleszámítjuk a végső hangerőbe.
    if normalization_enabled:
        filters.append(
            "loudnorm="
            f"I={normalization_target_lufs:.2f}:"
            f"TP={normalization_true_peak:.2f}:"
            "LRA=11"
        )

    # Ha nincs loudness normalizálás, pozitív EQ boostnál limiter véd.
    elif (
        eq_preamp_db > 0.05
        or any(
            value > 0.05
            for value in eq_band_values.values()
        )
    ):
        filters.append(
            "alimiter=limit=0.95"
        )

    return ",".join(
        filters
    )


def _eq_cache_path(track):
    path = str(
        track.get("path")
        or ""
    )

    try:
        modified = os.path.getmtime(
            path
        )
    except Exception:
        modified = 0

    bands_key = "|".join(
        f"{frequency}:{eq_band_values.get(frequency, 0.0):.2f}"
        for frequency, _ in EQ_BANDS
    )

    key = (
        f"{path}|{modified}|"
        f"preamp:{eq_preamp_db:.2f}|"
        f"{bands_key}|"
        f"norm:{int(normalization_enabled)}|"
        f"lufs:{normalization_target_lufs:.2f}|"
        f"tp:{normalization_true_peak:.2f}"
    )

    digest = hashlib.sha1(
        key.encode(
            "utf-8",
            errors="replace"
        )
    ).hexdigest()

    return os.path.join(
        EQ_CACHE,
        digest + ".mp3"
    )


def _set_eq_status(
    text,
    color=JM_MUTED
):
    try:
        if (
            eq_status_label is not None
            and eq_status_label.winfo_exists()
        ):
            eq_status_label.config(
                text=text,
                fg=color
            )
    except Exception:
        pass


def update_eq_ui():
    try:
        eq_button.config(
            text="EQ",
            fg=(
                JM_CYAN
                if eq_enabled
                else JM_TEXT
            )
        )
    except Exception:
        pass

    try:
        if (
            eq_preamp_value_label is not None
            and eq_preamp_value_label.winfo_exists()
        ):
            eq_preamp_value_label.config(
                text=f"{eq_preamp_db:+.1f} dB"
            )
    except Exception:
        pass

    for frequency, _ in EQ_BANDS:
        label = eq_band_value_labels.get(
            frequency
        )

        try:
            if (
                label is not None
                and label.winfo_exists()
            ):
                label.config(
                    text=(
                        f"{eq_band_values.get(frequency, 0.0):+.1f}"
                    )
                )
        except Exception:
            pass

    ffmpeg = _ffmpeg_path()

    if not ffmpeg:
        _set_eq_status(
            "FFmpeg nincs telepítve — az EQ feldolgozáshoz szükséges.",
            "#ff7777"
        )
    elif eq_enabled:
        _set_eq_status(
            "EQ: BE • 10 sávos valódi DSP aktív",
            JM_CYAN
        )
    else:
        _set_eq_status(
            "EQ: KI",
            JM_MUTED
        )


def _sync_eq_scales():
    for frequency, _ in EQ_BANDS:
        scale = eq_band_scales.get(
            frequency
        )

        try:
            if (
                scale is not None
                and scale.winfo_exists()
            ):
                scale.set(
                    eq_band_values.get(
                        frequency,
                        0.0
                    )
                )
        except Exception:
            pass

    try:
        if (
            eq_preamp_scale is not None
            and eq_preamp_scale.winfo_exists()
        ):
            eq_preamp_scale.set(
                eq_preamp_db
            )
    except Exception:
        pass


def set_eq_values(
    bands=None,
    preamp=None
):
    global eq_preamp_db

    if bands is not None:
        for frequency, value in bands.items():
            if frequency in eq_band_values:
                eq_band_values[
                    frequency
                ] = float(
                    value
                )

    if preamp is not None:
        eq_preamp_db = float(
            preamp
        )

    _sync_eq_scales()
    update_eq_ui()
    schedule_save_settings()


def _read_eq_scales():
    global eq_preamp_db

    for frequency, _ in EQ_BANDS:
        scale = eq_band_scales.get(
            frequency
        )

        try:
            if (
                scale is not None
                and scale.winfo_exists()
            ):
                eq_band_values[
                    frequency
                ] = float(
                    scale.get()
                )
        except Exception:
            pass

    try:
        if (
            eq_preamp_scale is not None
            and eq_preamp_scale.winfo_exists()
        ):
            eq_preamp_db = float(
                eq_preamp_scale.get()
            )
    except Exception:
        pass

    update_eq_ui()
    schedule_save_settings()


def apply_eq_to_current():
    _read_eq_scales()

    track = current_track()

    if track is None:
        update_eq_ui()
        return

    if (
        eq_enabled
        and not _ffmpeg_path()
    ):
        messagebox.showerror(
            "JustMusic! - EQ",
            (
                "A valódi 10 sávos Equalizerhez FFmpeg kell.\n\n"
                "Az EQ nem fog kamu effektet alkalmazni."
            ),
            parent=root
        )
        return

    position = (
        get_current_position()
        if song_started
        else 0.0
    )

    was_paused = bool(
        paused
    )

    play_song(
        start_position=position,
        start_paused=was_paused
    )


def toggle_eq():
    global eq_enabled

    eq_enabled = not eq_enabled

    update_eq_ui()
    schedule_save_settings()

    if current_track() is not None:
        apply_eq_to_current()


def _preset_bands(**values):
    result = {
        frequency: 0.0
        for frequency, _ in EQ_BANDS
    }

    for key, value in values.items():
        frequency = int(
            key.replace(
                "hz",
                ""
            )
        )

        if frequency in result:
            result[
                frequency
            ] = float(
                value
            )

    return result


