def clear_eq_cache():
    removed = 0

    try:
        for name in os.listdir(
            EQ_CACHE
        ):
            path = os.path.join(
                EQ_CACHE,
                name
            )

            if os.path.isfile(
                path
            ):
                try:
                    os.remove(
                        path
                    )
                    removed += 1
                except Exception:
                    pass

    except Exception:
        pass

    messagebox.showinfo(
        "JustMusic! - EQ",
        f"EQ cache törölve: {removed} fájl.",
        parent=eq_window or root
    )


def _process_eq_file(
    track,
    output_path
):
    ffmpeg = _ffmpeg_path()

    if not ffmpeg:
        raise RuntimeError(
            "FFmpeg nem található."
        )

    filter_string = _eq_filter_string()

    if not filter_string:
        return track["path"]

    temp_path = (
        output_path
        + ".part.mp3"
    )

    command = [
        ffmpeg,
        "-y",
        "-hide_banner",
        "-loglevel",
        "error",
        "-i",
        track["path"],
        "-vn",
        "-af",
        filter_string,
        "-c:a",
        "libmp3lame",
        "-q:a",
        "2",
        temp_path,
    ]

    try:
        result = subprocess.run(
            command,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            creationflags=(
                subprocess.CREATE_NO_WINDOW
                if os.name == "nt"
                and hasattr(
                    subprocess,
                    "CREATE_NO_WINDOW"
                )
                else 0
            )
        )

        if result.returncode != 0:
            raise RuntimeError(
                result.stderr.strip()
                or "FFmpeg EQ feldolgozási hiba."
            )

        os.replace(
            temp_path,
            output_path
        )

        return output_path

    finally:
        try:
            if os.path.exists(
                temp_path
            ):
                os.remove(
                    temp_path
                )
        except Exception:
            pass


def _prepare_eq_async(
    track,
    request_id,
    start_position,
    start_paused
):
    output_path = _eq_cache_path(
        track
    )

    if os.path.isfile(
        output_path
    ):
        _start_track_playback(
            track,
            output_path,
            request_id,
            start_position,
            start_paused
        )
        return

    _set_eq_status(
        "Audio feldolgozás folyamatban…",
        JM_CYAN
    )

    try:
        current_label.config(
            text=(
                f'{track["artist"]} — '
                f'{_clean_track_title_for_search(track["title"])}'
                "  •  audio feldolgozás…"
            )
        )
    except Exception:
        pass

    def worker():
        try:
            processed = _process_eq_file(
                track,
                output_path
            )

            root.after(
                0,
                lambda:
                    _eq_ready(
                        track,
                        processed,
                        request_id,
                        start_position,
                        start_paused
                    )
            )

        except Exception as error:
            root.after(
                0,
                lambda e=error:
                    _eq_failed(
                        track,
                        e,
                        request_id,
                        start_position,
                        start_paused
                    )
            )

    threading.Thread(
        target=worker,
        daemon=True
    ).start()


def _eq_ready(
    track,
    processed_path,
    request_id,
    start_position,
    start_paused
):
    _set_eq_status(
        "EQ: kész • cache-elve",
        JM_CYAN
    )

    _start_track_playback(
        track,
        processed_path,
        request_id,
        start_position,
        start_paused
    )


def _eq_failed(
    track,
    error,
    request_id,
    start_position,
    start_paused
):
    print(
        "EQ HIBA:",
        error
    )

    _set_eq_status(
        "EQ hiba — eredeti hang indul.",
        "#ff7777"
    )

    messagebox.showerror(
        "JustMusic! - EQ hiba",
        (
            "Az EQ feldolgozás nem sikerült.\n\n"
            f"{error}\n\n"
            "A szám az eredeti hanggal indul."
        ),
        parent=root
    )

    _start_track_playback(
        track,
        track["path"],
        request_id,
        start_position,
        start_paused
    )


def open_eq_window():
    global eq_window
    global eq_status_label
