# =========================================================
# DRAG & DROP - QUEUE / PLAYLIST
# =========================================================

def _drop_target_index(
    container,
    attr_name
):
    """
    Megnézi, melyik sor fölött van éppen az egér.
    A sorokon egyedi index attribútumot használunk.
    """
    try:
        pointer_y = root.winfo_pointery()
    except Exception:
        return None

    candidates = []

    try:
        children = container.winfo_children()
    except Exception:
        return None

    for child in children:
        if not hasattr(
            child,
            attr_name
        ):
            continue

        try:
            top = child.winfo_rooty()
            height = max(
                child.winfo_height(),
                1
            )
            middle = top + height / 2

            candidates.append(
                (
                    middle,
                    getattr(
                        child,
                        attr_name
                    )
                )
            )
        except Exception:
            pass

    if not candidates:
        return None

    candidates.sort(
        key=lambda item: item[0]
    )

    for middle, index in candidates:
        if pointer_y < middle:
            return index

    return candidates[-1][1]


def begin_queue_drag(index):
    global queue_drag_index

    queue_drag_index = index


def end_queue_drag(event=None):
    global queue_drag_index

    if queue_drag_index is None:
        return

    source_index = queue_drag_index
    queue_drag_index = None

    if not (
        0 <= source_index < len(
            play_queue
        )
    ):
        return

    target_index = _drop_target_index(
        queue_list_frame,
        "_queue_index"
    )

    if target_index is None:
        return

    target_index = int(
        target_index
    )

    if target_index == source_index:
        return

    item = play_queue.pop(
        source_index
    )

    target_index = max(
        0,
        min(
            target_index,
            len(
                play_queue
            )
        )
    )

    play_queue.insert(
        target_index,
        item
    )

    refresh_queue_window()


def begin_playlist_drag(
    playlist_name,
    path
):
    global playlist_drag_name
    global playlist_drag_path

    playlist_drag_name = playlist_name
    playlist_drag_path = path


def end_playlist_drag(event=None):
    global playlist_drag_name
    global playlist_drag_path

    name = playlist_drag_name
    source_path = playlist_drag_path

    playlist_drag_name = None
    playlist_drag_path = None

    if (
        not name
        or not source_path
        or name not in playlists
    ):
        return

    rows = []

    try:
        for child in song_list_frame.winfo_children():
            if (
                hasattr(
                    child,
                    "_playlist_path"
                )
                and getattr(
                    child,
                    "_playlist_name",
                    None
                ) == name
            ):
                rows.append(
                    child
                )
    except Exception:
        return

    if not rows:
        return

    try:
        pointer_y = root.winfo_pointery()
    except Exception:
        return

    target_path = None

    for child in rows:
        try:
            middle = (
                child.winfo_rooty()
                + child.winfo_height() / 2
            )

            if pointer_y < middle:
                target_path = getattr(
                    child,
                    "_playlist_path"
                )
                break
        except Exception:
            pass

    if target_path is None:
        target_path = getattr(
            rows[-1],
            "_playlist_path"
        )

    if target_path == source_path:
        return

    paths = playlists.get(
        name,
        []
    )

    if (
        source_path not in paths
        or target_path not in paths
    ):
        return

    paths.remove(
        source_path
    )

    target_index = paths.index(
        target_path
    )

    # Ha lefelé húzzuk, a cél mögé kerüljön természetesebben.
    try:
        source_y = next(
            child.winfo_rooty()
            for child in rows
            if getattr(
                child,
                "_playlist_path",
                None
            ) == source_path
        )

        target_y = next(
            child.winfo_rooty()
            for child in rows
            if getattr(
                child,
                "_playlist_path",
                None
            ) == target_path
        )

        if pointer_y > target_y and source_y < target_y:
            target_index += 1
    except Exception:
        pass

    target_index = max(
        0,
        min(
            target_index,
            len(
                paths
            )
        )
    )

    paths.insert(
        target_index,
        source_path
    )

    save_playlists()
    show_playlist_tracks(
        name
    )
    refresh_playlist_window()



# =========================================================
# PLAYLISTEK
# =========================================================

def load_playlists():
    global playlists

    playlists = {}

    try:
        with open(
            PLAYLISTS_FILE,
            "r",
            encoding="utf-8"
        ) as file:
            data = json.load(file)

        if isinstance(data, dict):
            playlists = {
                str(name): [
                    str(path)
                    for path in paths
                    if isinstance(path, str)
                ]
                for name, paths in data.items()
                if isinstance(paths, list)
            }

    except Exception:
        playlists = {}


def save_playlists():
    try:
        with open(
            PLAYLISTS_FILE,
            "w",
            encoding="utf-8"
        ) as file:
            json.dump(
                playlists,
                file,
                ensure_ascii=False,
                indent=2
            )

    except Exception as error:
        print(
            "PLAYLIST MENTÉSI HIBA:",
            error
        )


def playlist_tracks(name):
    paths = playlists.get(
        name,
        []
    )

    by_path = {
        track["path"]: track
        for track in library
    }

    return [
        by_path[path]
        for path in paths
        if path in by_path
    ]


def create_playlist():
    name = simpledialog.askstring(
        "JustMusic! - Új playlist",
        "Mi legyen a playlist neve?",
        parent=root
    )

    if not name:
        return

    name = name.strip()

    if not name:
        return

    if name in playlists:
        messagebox.showinfo(
            "JustMusic!",
            "Már létezik ilyen nevű playlist.",
            parent=root
        )
        return

    playlists[name] = []
    save_playlists()
    refresh_playlist_window()


def delete_playlist(name):
    if name not in playlists:
        return

    answer = messagebox.askyesno(
        "JustMusic!",
        f'Biztosan törlöd ezt a playlistet?\n\n{name}',
        parent=root
    )

    if not answer:
        return

    playlists.pop(
        name,
        None
    )

    save_playlists()
    refresh_playlist_window()


def add_track_to_playlist(track, playlist_name=None):
    if not track:
        return

    if not playlists:
        create_playlist()

        if not playlists:
            return

    if playlist_name is None:
        names = list(
            playlists.keys()
        )

        chooser = tk.Toplevel(root)
        chooser.title(
            "JustMusic! - Playlist választása"
        )
        chooser.geometry(
            "420x420"
        )
        chooser.configure(
            bg=JM_BG
        )

        tk.Label(
            chooser,
            text="HOZZÁADÁS PLAYLISTHEZ",
            font=("Arial", 15, "bold"),
            fg=JM_CYAN,
            bg=JM_BG
        ).pack(
            pady=(18, 4)
        )

        tk.Label(
            chooser,
            text=f'{track["artist"]} — {track["title"]}',
            font=("Arial", 10, "bold"),
            fg=JM_TEXT,
            bg=JM_BG,
            wraplength=360,
            justify="center"
        ).pack(
            pady=(0, 14),
            padx=20
        )

        tk.Button(
            chooser,
            text="＋ ÚJ PLAYLIST",
            command=lambda: (
                chooser.destroy(),
                create_playlist()
            ),
            bg=JM_PANEL_2,
            fg=JM_TEXT,
            activebackground=JM_CARD_HOVER,
            activeforeground=JM_CYAN,
            borderwidth=0,
            relief="flat",
            font=("Arial", 9, "bold"),
            padx=12,
            pady=7
        ).pack(
            pady=(0, 10)
        )

        list_box = tk.Frame(
            chooser,
            bg=JM_BG
        )
        list_box.pack(
            fill="both",
            expand=True,
            padx=18,
            pady=(0, 18)
        )

        def choose(name):
            chooser.destroy()
            add_track_to_playlist(
                track,
                name
            )

        for name in names:
            tk.Button(
                list_box,
                text=f'{name}  •  {len(playlists.get(name, []))} dal',
                command=lambda n=name:
                    choose(n),
                anchor="w",
                bg=JM_PANEL,
                fg=JM_TEXT,
                activebackground=JM_PANEL_2,
                activeforeground=JM_CYAN,
                borderwidth=0,
                relief="flat",
                font=("Arial", 10, "bold"),
                padx=12,
                pady=9
            ).pack(
                fill="x",
                pady=3
            )

        return

    paths = playlists.setdefault(
        playlist_name,
        []
    )

    path = track["path"]

    if path in paths:
        messagebox.showinfo(
            "JustMusic!",
            f'Már benne van ebben a playlistben:\n{playlist_name}',
            parent=root
        )
        return

    paths.append(
        path
    )

    save_playlists()
    refresh_playlist_window()

    messagebox.showinfo(
        "JustMusic!",
        (
            "✅ Hozzáadva a playlisthez!\n\n"
            f'{playlist_name}\n'
            f'{track["artist"]} — {track["title"]}'
        ),
        parent=root
    )


def remove_track_from_playlist(name, path):
    paths = playlists.get(
        name,
        []
    )

    if path in paths:
        paths.remove(path)
        save_playlists()

    show_playlist_tracks(
        name
    )

    refresh_playlist_window()


