def _waveform_key(track):
    path = str(
        track.get("path")
        or ""
    )

    try:
        modified = os.path.getmtime(
            path
        )
    except Exception:
        modified = 0

    return (
        path,
        modified
    )


def _extract_waveform_points(track, points=260):
    """
    Valódi waveform FFmpeg PCM adatokból.
    Nem random/pseudo vizualizáció.
    """
    ffmpeg = _ffmpeg_path()

    if not ffmpeg:
        raise RuntimeError(
            "FFmpeg nem található."
        )

    command = [
        ffmpeg,
        "-hide_banner",
        "-loglevel",
        "error",
        "-i",
        track["path"],
        "-vn",
        "-ac",
        "1",
        "-ar",
        "400",
        "-f",
        "s16le",
        "-"
    ]

    result = subprocess.run(
        command,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        creationflags=(
            subprocess.CREATE_NO_WINDOW
            if os.name == "nt"
            and hasattr(
                subprocess,
                "CREATE_NO_WINDOW"
            )
            else 0
        )
    )

    if result.returncode != 0:
        raise RuntimeError(
            result.stderr.decode(
                "utf-8",
                errors="replace"
            ).strip()
            or "Waveform feldolgozási hiba."
        )

    samples = array("h")
    samples.frombytes(
        result.stdout
    )

    if not samples:
        return [
            0.0
            for _ in range(points)
        ]

    total = len(samples)
    values = []

    for index in range(points):
        start = int(
            index
            * total
            / points
        )

        end = int(
            (index + 1)
            * total
            / points
        )

        if end <= start:
            end = min(
                start + 1,
                total
            )

        chunk = samples[
            start:end
        ]

        if not chunk:
            values.append(
                0.0
            )
            continue

        peak = max(
            abs(sample)
            for sample in chunk
        )

        values.append(
            min(
                1.0,
                peak / 32768.0
            )
        )

    return values


def _render_waveform(points, progress_fraction=None):
    canvas_widget = now_playing_wave_canvas

    try:
        if (
            canvas_widget is None
            or not canvas_widget.winfo_exists()
        ):
            return
    except Exception:
        return

    canvas_widget.delete(
        "all"
    )

    width = max(
        canvas_widget.winfo_width(),
        760
    )

    height = max(
        canvas_widget.winfo_height(),
        120
    )

    center_y = height / 2
    margin_x = 10
    usable_width = max(
        width - margin_x * 2,
        1
    )

    if not points:
        canvas_widget.create_text(
            width / 2,
            center_y,
            text="Waveform nem érhető el",
            fill=JM_MUTED,
            font=("Arial", 10, "bold")
        )
        return

    count = len(points)
    bar_width = max(
        1.0,
        usable_width / count
    )

    for i, value in enumerate(points):
        x = (
            margin_x
            + i * bar_width
        )

        amplitude = max(
            2,
            value
            * (height * 0.42)
        )

        canvas_widget.create_line(
            x,
            center_y - amplitude,
            x,
            center_y + amplitude,
            fill="#5a5a5a",
            width=max(
                1,
                int(bar_width * 0.55)
            )
        )

    if progress_fraction is not None:
        progress_fraction = max(
            0.0,
            min(
                1.0,
                float(progress_fraction)
            )
        )

        progress_x = (
            margin_x
            + usable_width
            * progress_fraction
        )

        # Bal oldali, már lejátszott rész zöld overlay.
        played_count = int(
            count
            * progress_fraction
        )

        for i in range(
            min(
                played_count,
                count
            )
        ):
            value = points[i]

            x = (
                margin_x
                + i * bar_width
            )

            amplitude = max(
                2,
                value
                * (height * 0.42)
            )

            canvas_widget.create_line(
                x,
                center_y - amplitude,
                x,
                center_y + amplitude,
                fill=JM_CYAN,
                width=max(
                    1,
                    int(bar_width * 0.55)
                )
            )

        canvas_widget.create_line(
            progress_x,
            8,
            progress_x,
            height - 8,
            fill=JM_TEXT,
            width=2
        )


def _waveform_ready(track_key, points):
    waveform_loading.discard(
        track_key
    )

    waveform_cache[
        track_key
    ] = points

    track = current_track()

    if track is None:
        return

    if _waveform_key(
        track
    ) != track_key:
        return

    try:
        if (
            now_playing_wave_status is not None
            and now_playing_wave_status.winfo_exists()
        ):
            now_playing_wave_status.config(
                text=""
            )
    except Exception:
        pass

    current_seconds = (
        get_current_position()
        if song_started
        else 0.0
    )

    fraction = (
        current_seconds / song_length
        if song_length > 0
        else 0.0
    )

    _render_waveform(
        points,
        fraction
    )


def _waveform_failed(track_key, error):
    waveform_loading.discard(
        track_key
    )

    print(
        "WAVEFORM HIBA:",
        error
    )

    try:
        if (
            now_playing_wave_status is not None
            and now_playing_wave_status.winfo_exists()
        ):
            now_playing_wave_status.config(
                text="Waveform nem tölthető be."
            )
    except Exception:
        pass


def ensure_waveform(track):
    if track is None:
        return

    key = _waveform_key(
        track
    )

    if key in waveform_cache:
        current_seconds = (
            get_current_position()
            if song_started
            else 0.0
        )

        fraction = (
            current_seconds / song_length
            if song_length > 0
            else 0.0
        )

        _render_waveform(
            waveform_cache[key],
            fraction
        )
        return

    if key in waveform_loading:
        return

    waveform_loading.add(
        key
    )

    try:
        if (
            now_playing_wave_status is not None
            and now_playing_wave_status.winfo_exists()
        ):
            now_playing_wave_status.config(
                text="Waveform elemzése…"
            )
    except Exception:
        pass

    def worker():
        try:
            points = _extract_waveform_points(
                track,
                points=260
            )

            root.after(
                0,
                lambda:
                    _waveform_ready(
                        key,
                        points
                    )
            )

        except Exception as error:
            root.after(
                0,
                lambda e=error:
                    _waveform_failed(
                        key,
                        e
                    )
            )

    threading.Thread(
        target=worker,
        daemon=True
    ).start()



def _visualizer_energy(current_seconds):
    track = current_track()

    if track is None:
        return 0.0, []

    key = _waveform_key(
        track
    )

    points = waveform_cache.get(
        key,
        []
    )

    if not points:
        return (
            0.16
            if song_started and not paused
            else 0.05
        ), []

    if song_length <= 0:
        index = 0
    else:
        fraction = max(
            0.0,
            min(
                1.0,
                float(current_seconds)
                / float(song_length)
            )
        )

        index = min(
            len(points) - 1,
            int(
                fraction
                * len(points)
            )
        )

    start = max(
        0,
        index - 3
    )

    end = min(
        len(points),
        index + 4
    )

    local = points[
        start:end
    ]

    if not local:
        return 0.05, points

    energy = sum(
        local
    ) / len(local)

    return max(
        0.04,
        min(
            1.0,
            energy
        )
    ), points


def _visualizer_values(
    current_seconds,
    bar_count
):
    global visualizer_phase

    energy, points = _visualizer_energy(
        current_seconds
    )

    if (
        not song_started
        or paused
        or not visualizer_enabled
    ):
        energy *= 0.25

    visualizer_phase += (
        0.24
        if song_started and not paused
        else 0.07
    )

    values = []

    if points and song_length > 0:
        base_index = min(
            len(points) - 1,
            int(
                max(
                    0.0,
                    min(
                        1.0,
                        current_seconds
                        / song_length
                    )
                )
                * len(points)
            )
        )
    else:
        base_index = 0

    for index in range(
        bar_count
    ):
        x = (
            index
            / max(
                bar_count - 1,
                1
            )
        )

        # Alacsony frekvenciás érzet: bal oldalon picit erősebb.
        bass_shape = (
            1.10
            - 0.32 * x
        )

        wave_motion = (
            0.56
            + 0.24
            * math.sin(
                visualizer_phase
                + index * 0.54
            )
            + 0.12
            * math.sin(
                visualizer_phase * 0.57
                + index * 1.13
            )
        )

        if points:
            sample_index = (
                base_index
                + index * 3
                - bar_count
            ) % len(points)

            real_shape = (
                0.40
                + points[
                    sample_index
                ]
                * 0.90
            )
        else:
            real_shape = 0.58

        value = (
            energy
            * bass_shape
            * max(
                0.15,
                wave_motion
            )
            * real_shape
        )

        # kis minimum, hogy csendben se legyen teljesen halott
        value = max(
            0.035,
            min(
                1.0,
                value
            )
        )

        values.append(
            value
        )

    return values


def _draw_visualizer(
    canvas_widget,
    current_seconds=None,
    compact=False
):
    if canvas_widget is None:
        return

    try:
        if not canvas_widget.winfo_exists():
            return
    except Exception:
        return

    canvas_widget.delete(
        "all"
    )

    width = max(
        canvas_widget.winfo_width(),
        260
        if compact
        else 520
    )

    height = max(
        canvas_widget.winfo_height(),
        48
        if compact
        else 90
    )

    if current_seconds is None:
        current_seconds = (
            get_current_position()
            if song_started
            else 0.0
        )

    if not visualizer_enabled:
        canvas_widget.create_text(
            width / 2,
            height / 2,
            text="VIZUALIZÁTOR KI",
            fill=JM_MUTED,
            font=(
                "Arial",
                8,
                "bold"
            )
        )
        return

    bar_count = (
        22
        if compact
        else 44
    )

    values = _visualizer_values(
        current_seconds,
        bar_count
    )

    gap = (
        2
        if compact
        else 3
    )

    bar_width = max(
        2.0,
        (
            width
            - gap * (
                bar_count - 1
            )
        )
        / bar_count
    )

    if visualizer_style == "pulse":
        energy = (
            sum(values)
            / len(values)
            if values
            else 0.0
        )

        radius = (
            min(
                width,
                height
            )
            * (
                0.18
                + energy * 0.27
            )
        )

        cx = width / 2
        cy = height / 2

        canvas_widget.create_oval(
            cx - radius,
            cy - radius,
            cx + radius,
            cy + radius,
            outline=JM_CYAN,
            width=3
        )

        canvas_widget.create_oval(
            cx - radius * 0.55,
            cy - radius * 0.55,
            cx + radius * 0.55,
            cy + radius * 0.55,
            fill="#1d4458",
            outline=""
        )

        canvas_widget.create_text(
            cx,
            cy,
            text="♪",
            fill=JM_TEXT,
            font=(
                "Arial",
                16
                if compact
                else 22,
                "bold"
            )
        )

        return

    center_y = height / 2

    for index, value in enumerate(
        values
    ):
        x1 = (
            index
            * (
                bar_width
                + gap
            )
        )

        x2 = x1 + bar_width

        if visualizer_style == "mirror":
            amplitude = max(
                2,
                value
                * (
                    height * 0.46
                )
            )

            y1 = center_y - amplitude
            y2 = center_y + amplitude

        else:
            amplitude = max(
                2,
                value
                * (
                    height * 0.88
                )
            )

            y1 = height - amplitude
            y2 = height

        # Erősebb oszlopok fehérednek, a többi világoskék.
        if value > 0.68:
            fill = JM_TEXT
        elif value > 0.38:
            fill = JM_CYAN_BRIGHT
        else:
            fill = JM_CYAN

        canvas_widget.create_rectangle(
            x1,
            y1,
            x2,
            y2,
            fill=fill,
            outline=""
        )


def cycle_visualizer_style():
    global visualizer_style

    order = [
        "bars",
        "mirror",
        "pulse",
    ]

    try:
        index = order.index(
            visualizer_style
        )
    except ValueError:
        index = 0

    visualizer_style = order[
        (
            index + 1
        )
        % len(order)
    ]

    refresh_visualizer_labels()


def toggle_visualizer():
    global visualizer_enabled

    visualizer_enabled = (
        not visualizer_enabled
    )

    refresh_visualizer_labels()


def refresh_visualizer_labels():
    text_map = {
        "bars": "BARS",
        "mirror": "MIRROR",
        "pulse": "PULSE",
    }

    state_text = (
        text_map.get(
            visualizer_style,
            "BARS"
        )
        if visualizer_enabled
        else "KI"
    )

    try:
        if (
            now_playing_visualizer_label is not None
            and now_playing_visualizer_label.winfo_exists()
        ):
            now_playing_visualizer_label.config(
                text=(
                    "VIZUALIZÁTOR  •  "
                    + state_text
                )
            )
    except Exception:
        pass


