def _now_playing_mode_text():
    parts = []

    if shuffle_enabled:
        parts.append(
            "SHUFFLE"
        )

    if repeat_mode == "all":
        parts.append(
            "REPEAT ALL"
        )
    elif repeat_mode == "one":
        parts.append(
            "REPEAT ONE"
        )

    if mix_gapless_enabled:
        parts.append(
            "GAPLESS"
        )
    elif crossfade_enabled:
        parts.append(
            f"MIX {mix_fade_out_seconds:.1f}/{mix_fade_in_seconds:.1f}s"
        )

    if mix_dj_mode_enabled:
        parts.append(
            "DJ"
        )

    if eq_enabled:
        parts.append(
            "EQ"
        )

    if normalization_enabled:
        parts.append(
            f"RG {normalization_target_lufs:.0f} LUFS"
        )

    if play_queue:
        parts.append(
            f"QUEUE {len(play_queue)}"
        )

    return (
        "   •   ".join(parts)
        if parts
        else "NORMAL"
    )


def update_now_playing_progress(current_seconds=None):
    try:
        if (
            now_playing_window is None
            or not now_playing_window.winfo_exists()
        ):
            return
    except Exception:
        return

    if current_seconds is None:
        current_seconds = (
            get_current_position()
            if song_started
            else 0.0
        )

    try:
        now_playing_elapsed_label.config(
            text=format_time(
                current_seconds
            )
        )

        now_playing_total_label.config(
            text=format_time(
                song_length
            )
        )

        now_playing_mode_label.config(
            text=_now_playing_mode_text()
        )
    except Exception:
        pass

    track = current_track()

    if track is None:
        return

    key = _waveform_key(
        track
    )

    points = waveform_cache.get(
        key
    )

    if points:
        fraction = (
            current_seconds / song_length
            if song_length > 0
            else 0.0
        )

        _render_waveform(
            points,
            fraction
        )


