def close_fullscreen_lyrics(event=None):
    global full_lyrics_window
    global full_lyrics_canvas
    global full_lyrics_frame
    global full_lyrics_canvas_window
    global full_lyrics_labels
    global full_lyrics_title_label
    global full_lyrics_artist_label
    global full_lyrics_time_label
    global full_lyrics_signature
    global full_lyrics_active_index

    try:
        if (
            full_lyrics_window is not None
            and full_lyrics_window.winfo_exists()
        ):
            full_lyrics_window.destroy()
    except Exception:
        pass

    full_lyrics_window = None
    full_lyrics_canvas = None
    full_lyrics_frame = None
    full_lyrics_canvas_window = None
    full_lyrics_labels = []
    full_lyrics_title_label = None
    full_lyrics_artist_label = None
    full_lyrics_time_label = None
    full_lyrics_signature = None
    full_lyrics_active_index = -1


def _full_lyrics_current_index(current_seconds):
    if not lyrics:
        return -1

    current_seconds += LYRICS_OFFSET
    index = -1

    for i, (start_time, _) in enumerate(lyrics):
        if current_seconds >= start_time:
            index = i
        else:
            break

    return index


def _full_lyrics_signature():
    track = current_track()

    if track is None:
        return None

    if not lyrics:
        return (
            track.get("path"),
            0
        )

    return (
        track.get("path"),
        len(lyrics),
        lyrics[0][0],
        lyrics[-1][0],
        lyrics[0][1],
        lyrics[-1][1],
    )


def _schedule_full_lyrics_rebuild(delay=80):
    try:
        if (
            full_lyrics_canvas is None
            or not full_lyrics_canvas.winfo_exists()
        ):
            return

        after_id = getattr(
            full_lyrics_canvas,
            "_jm_rebuild_after",
            None
        )

        if after_id is not None:
            full_lyrics_canvas.after_cancel(after_id)

        full_lyrics_canvas._jm_rebuild_after = full_lyrics_canvas.after(
            delay,
            rebuild_fullscreen_lyrics
        )
    except Exception:
        pass


def _sync_full_lyrics_background():
    """A koncert-háttér mindig a látható dalszöveg-résszel együtt marad."""
    try:
        if (
            full_lyrics_canvas is None
            or not full_lyrics_canvas.winfo_exists()
        ):
            return

        state = getattr(
            full_lyrics_canvas,
            "_jm_party_bg_state",
            None
        )

        if not state:
            return

        image_id = state.get("image_id")

        if image_id is None:
            return

        region = str(
            full_lyrics_canvas.cget("scrollregion")
        ).split()

        if len(region) != 4:
            return

        x1, y1, x2, y2 = map(float, region)
        total_width = max(x2 - x1, 1.0)
        total_height = max(y2 - y1, 1.0)

        x_fraction = full_lyrics_canvas.xview()[0]
        y_fraction = full_lyrics_canvas.yview()[0]

        visible_x = x1 + x_fraction * total_width
        visible_y = y1 + y_fraction * total_height

        full_lyrics_canvas.coords(
            image_id,
            visible_x,
            visible_y
        )

        full_lyrics_canvas.tag_lower(
            image_id
        )

    except Exception:
        pass


def _resize_full_lyrics_canvas(event=None):
    _schedule_full_lyrics_rebuild(90)
    root.after_idle(_sync_full_lyrics_background)


def _center_full_lyrics_line(index):
    if not (
        full_lyrics_canvas is not None
        and full_lyrics_labels
        and 0 <= index < len(full_lyrics_labels)
    ):
        return

    try:
        bbox = full_lyrics_canvas.bbox(
            full_lyrics_labels[index]
        )

        scroll_bbox = full_lyrics_canvas.bbox("all")

        if not bbox or not scroll_bbox:
            return

        total_height = max(
            float(scroll_bbox[3] - scroll_bbox[1]),
            1.0
        )

        viewport_height = max(
            float(full_lyrics_canvas.winfo_height()),
            1.0
        )

        item_center = (
            float(bbox[1])
            + float(bbox[3] - bbox[1]) / 2.0
        )

        wanted_top = item_center - viewport_height * 0.46
        max_top = max(total_height - viewport_height, 0.0)
        wanted_top = max(0.0, min(wanted_top, max_top))

        fraction = (
            wanted_top / total_height
            if total_height > 0
            else 0.0
        )

        full_lyrics_canvas.yview_moveto(fraction)
        _sync_full_lyrics_background()

    except Exception as error:
        print(
            "FULLSCREEN LYRICS SCROLL HIBA:",
            error
        )


def rebuild_fullscreen_lyrics():
    global full_lyrics_labels
    global full_lyrics_signature
    global full_lyrics_active_index
    global full_lyrics_title_label
    global full_lyrics_artist_label
    global full_lyrics_time_label

    try:
        if (
            full_lyrics_window is None
            or not full_lyrics_window.winfo_exists()
            or full_lyrics_canvas is None
            or not full_lyrics_canvas.winfo_exists()
        ):
            return
    except Exception:
        return

    track = current_track()

    if track is None:
        return

    try:
        full_lyrics_canvas.delete("jm_lyric_ui")
    except Exception:
        pass

    if not getattr(full_lyrics_canvas, "_jm_party_canvas_bg", False):
        full_lyrics_canvas._jm_party_bg_state = install_party_canvas_background(
            full_lyrics_canvas,
            brightness=0.38,
            blur=1.25,
            saturation=1.02
        )
        full_lyrics_canvas._jm_party_canvas_bg = True
    else:
        _sync_full_lyrics_background()

    width = max(900, full_lyrics_canvas.winfo_width())
    height = max(600, full_lyrics_canvas.winfo_height())

    display_title = _clean_track_title_for_search(
        track.get(
            "title",
            ""
        )
    )

    display_artist = track.get(
        "artist",
        ""
    )

    full_lyrics_labels = []
    full_lyrics_active_index = -1
    full_lyrics_signature = _full_lyrics_signature()

    # Felső bal sarok: app + mód
    full_lyrics_title_label = full_lyrics_canvas.create_text(
        58,
        42,
        text="JustMusic!  •  Fullscreen Lyrics",
        fill=JM_TEXT,
        font=("Arial", 22, "bold"),
        anchor="nw",
        tags=("jm_lyric_ui",)
    )

    full_lyrics_artist_label = full_lyrics_canvas.create_text(
        58,
        82,
        text=f"{display_title}  •  {display_artist}" if display_artist else display_title,
        fill="#D6E8F8",
        font=("Arial", 12, "bold"),
        anchor="nw",
        tags=("jm_lyric_ui",)
    )

    full_lyrics_time_label = full_lyrics_canvas.create_text(
        width - 58,
        56,
        text=f"{format_time(0.0)}  /  {format_time(song_length)}",
        fill="#6FD8FF",
        font=("Arial", 12, "bold"),
        anchor="ne",
        tags=("jm_lyric_ui",)
    )

    hint_text = "ESC = vissza    •    Kattints egy sorra = oda tekerés"

    full_lyrics_canvas.create_text(
        width - 58,
        height - 32,
        text=hint_text,
        fill=JM_TEXT_2,
        font=("Arial", 10, "bold"),
        anchor="se",
        tags=("jm_lyric_ui",)
    )

    if not lyrics:
        full_lyrics_canvas.create_text(
            width / 2,
            height / 2 - 24,
            text="Nincs még szinkronizált dalszöveg ehhez a számhoz.",
            fill=JM_TEXT,
            font=("Arial", 28, "bold"),
            width=max(420, width - 220),
            justify="center",
            tags=("jm_lyric_ui",)
        )

        full_lyrics_canvas.create_text(
            width / 2,
            height / 2 + 34,
            text="Ha van .lrc fájl, a JustMusic! automatikusan itt fogja megjeleníteni.",
            fill=JM_TEXT_2,
            font=("Arial", 14, "bold"),
            width=max(420, width - 240),
            justify="center",
            tags=("jm_lyric_ui",)
        )

        full_lyrics_canvas.configure(
            scrollregion=(0, 0, width, height)
        )
        return

    top_space = max(200, int(height * 0.24))
    line_gap = 78
    text_width = max(500, width - 280)

    y = top_space

    for index, (start_time, text) in enumerate(lyrics):
        item = full_lyrics_canvas.create_text(
            width / 2,
            y,
            text=text,
            fill="#9DB9D3",
            font=("Arial", 25, "bold"),
            width=text_width,
            justify="center",
            anchor="n",
            tags=("jm_lyric_ui", "jm_lyric_line")
        )

        full_lyrics_canvas.tag_bind(
            item,
            "<Button-1>",
            lambda event, ts=start_time: seek_to_lyric_time(ts)
        )

        full_lyrics_labels.append(item)
        y += line_gap

    total_height = max(
        height,
        y + 280
    )

    full_lyrics_canvas.configure(
        scrollregion=(0, 0, width, total_height)
    )

    _sync_full_lyrics_background()
    update_fullscreen_lyrics()


def update_fullscreen_lyrics(current_seconds=None):
    global full_lyrics_active_index
    global full_lyrics_signature

    try:
        if (
            full_lyrics_window is None
            or not full_lyrics_window.winfo_exists()
            or full_lyrics_canvas is None
            or not full_lyrics_canvas.winfo_exists()
        ):
            return
    except Exception:
        return

    track = current_track()

    if track is None:
        return

    signature = _full_lyrics_signature()

    if signature != full_lyrics_signature:
        rebuild_fullscreen_lyrics()
        signature = full_lyrics_signature

    if current_seconds is None:
        current_seconds = (
            get_current_position()
            if song_started
            else 0.0
        )

    try:
        if full_lyrics_time_label is not None:
            full_lyrics_canvas.itemconfig(
                full_lyrics_time_label,
                text=(
                    f"{format_time(current_seconds)}"
                    f"  /  {format_time(song_length)}"
                )
            )
    except Exception:
        pass

    _sync_full_lyrics_background()

    if not lyrics or not full_lyrics_labels:
        return

    new_index = _full_lyrics_current_index(current_seconds)

    if new_index == full_lyrics_active_index:
        return

    full_lyrics_active_index = new_index

    for index, item in enumerate(full_lyrics_labels):
        if index == new_index:
            # Aktuális sor: maximális kontraszt.
            full_lyrics_canvas.itemconfig(
                item,
                fill="#FFFFFF",
                font=("Arial", 36, "bold")
            )
        elif index == new_index - 1 or index == new_index + 1:
            # Szomszédos sorok: világos neon-kék.
            full_lyrics_canvas.itemconfig(
                item,
                fill="#CBEFFF",
                font=("Arial", 29, "bold")
            )
        else:
            # Távolabbi sorok: jól olvasható, de nem vonják el a figyelmet.
            full_lyrics_canvas.itemconfig(
                item,
                fill="#8FAFCB",
                font=("Arial", 25, "bold")
            )

    if 0 <= new_index < len(full_lyrics_labels):
        root.after_idle(
            lambda i=new_index: _center_full_lyrics_line(i)
        )

        root.after(
            90,
            lambda i=new_index: _center_full_lyrics_line(i)
        )


def open_fullscreen_lyrics():
    global full_lyrics_window
    global full_lyrics_canvas
    global full_lyrics_frame
    global full_lyrics_canvas_window
    global full_lyrics_title_label
    global full_lyrics_artist_label
    global full_lyrics_time_label
    global full_lyrics_signature
    global full_lyrics_active_index

    track = current_track()

    if track is None:
        messagebox.showinfo(
            "JustMusic!",
            "Előbb indíts el egy dalt.",
            parent=root
        )
        return

    try:
        if (
            full_lyrics_window is not None
            and full_lyrics_window.winfo_exists()
        ):
            full_lyrics_window.lift()
            full_lyrics_window.attributes(
                "-fullscreen",
                True
            )
            update_fullscreen_lyrics()
            return
    except Exception:
        pass

    full_lyrics_signature = None
    full_lyrics_active_index = -1

    full_lyrics_window = tk.Toplevel(root)
    full_lyrics_window.title(
        "JustMusic! - Teljes képernyős dalszöveg"
    )
    full_lyrics_window.configure(bg=JM_BG)
    full_lyrics_window.attributes("-fullscreen", True)
    full_lyrics_window.bind("<Escape>", close_fullscreen_lyrics)
    full_lyrics_window.protocol(
        "WM_DELETE_WINDOW",
        close_fullscreen_lyrics
    )

    install_party_background(
        full_lyrics_window,
        brightness=0.34,
        blur=1.35,
        saturation=1.00
    )

    full_lyrics_canvas = tk.Canvas(
        full_lyrics_window,
        bg=JM_BG,
        highlightthickness=0,
        borderwidth=0,
        yscrollincrement=1
    )
    full_lyrics_canvas.pack(fill="both", expand=True)

    # Régi változókat nullán tartjuk, hogy más részekkel kompatibilis maradjon.
    full_lyrics_frame = None
    full_lyrics_canvas_window = None

    exit_button = tk.Button(
        full_lyrics_window,
        text="✕",
        command=close_fullscreen_lyrics,
        bg="#0A1624",
        fg=JM_TEXT,
        activebackground="#11263D",
        activeforeground=JM_CYAN_BRIGHT,
        borderwidth=0,
        relief="flat",
        font=("Arial", 16, "bold"),
        padx=14,
        pady=6,
        cursor="hand2"
    )
    exit_button.place(
        relx=1.0,
        x=-28,
        y=22,
        anchor="ne"
    )

    def mousewheel(event):
        try:
            delta = getattr(event, "delta", 0)
            if delta:
                full_lyrics_canvas.yview_scroll(
                    int(-1 * (delta / 120)),
                    "units"
                )
                _sync_full_lyrics_background()
        except Exception:
            pass

    full_lyrics_canvas.bind("<Configure>", _resize_full_lyrics_canvas)
    full_lyrics_canvas.bind_all("<MouseWheel>", mousewheel)

    rebuild_fullscreen_lyrics()
    update_fullscreen_lyrics()


def refresh_now_playing_visuals(track=None):
    global bottom_cover_ref
    global now_playing_cover_ref
    global now_playing_wave_track_key

    if track is None:
        track = current_track()

    if track is None:
        return

    display_title = _clean_track_title_for_search(
        track["title"]
    )

    try:
        now_playing_small.config(
            text=display_title
        )

        now_playing_hint.config(
            text=track["artist"]
        )
    except Exception:
        pass

    try:
        cover = get_cover(
            track,
            (58, 58)
        )

        if cover:
            bottom_cover_ref = cover

            bottom_cover_label.config(
                image=cover,
                text=""
            )
        else:
            bottom_cover_label.config(
                image="",
                text="♫"
            )

    except Exception:
        pass

    try:
        if (
            now_playing_window is not None
            and now_playing_window.winfo_exists()
        ):
            full_cover = get_cover(
                track,
                (380, 380)
            )

            if full_cover:
                now_playing_cover_ref = full_cover

                now_playing_big_cover.config(
                    image=full_cover,
                    text=""
                )
            else:
                now_playing_big_cover.config(
                    image="",
                    text="♫"
                )

            now_playing_big_title.config(
                text=display_title
            )

            now_playing_big_artist.config(
                text=track["artist"]
            )

            album = track.get(
                "album",
                ""
            )

            if album.casefold() in {
                "ismeretlen album",
                "unknown album"
            }:
                album = ""

            now_playing_big_album.config(
                text=album
            )

            now_playing_wave_track_key = _waveform_key(
                track
            )

            ensure_waveform(
                track
            )

            update_now_playing_progress()

    except Exception:
        pass

    # A Mini Player is azonnal kapja az új címet / előadót / borítót.
    try:
        refresh_mini_player()
    except Exception:
        pass


