def format_time(seconds):
    seconds = int(max(0, seconds))
    return f"{seconds // 60}:{seconds % 60:02d}"


def get_song_length(path):
    try:
        sound = pygame.mixer.Sound(path)
        length = sound.get_length()
        del sound
        return length
    except Exception:
        return 0.0


def first_tag(tags, keys, fallback):
    if not tags:
        return fallback
    for key in keys:
        value = tags.get(key)
        if value:
            if isinstance(value, (list, tuple)):
                value = value[0]
            value = str(value).strip()
            if value:
                return value
    return fallback



def _clean_download_title(text):
    """
    Letöltött / YouTube-szerű fájlnevekből kiszedi a tipikus zajt.

    Példák:
    GATA ONLY (Video Official) _ EL COMIENZO (320 kbps) -> GATA ONLY
    Szálljon a Dal] -> Szálljon a Dal
    [Szálljon a Dal -> Szálljon a Dal
    """
    text = str(text or "").strip()

    # Tipikus zárójeles / szögletes videós vagy minőségi toldalékok.
    junk_group = re.compile(
        r"\s*[\(\[]\s*"
        r"(?:official\s*)?(?:music\s*)?(?:video|audio|lyrics?)"
        r"|(?:video|audio|lyrics?)\s*(?:official)?"
        r"|(?:\d{2,4}\s*kbps)"
        r"|(?:hd|full\s*hd|4k|8k)"
        r"|(?:visuali[sz]er)"
        r"|(?:clean|explicit)"
        r"|(?:remaster(?:ed)?(?:\s*\d{4})?)"
        r"\s*[\)\]]",
        flags=re.IGNORECASE
    )

    previous = None
    while previous != text:
        previous = text
        text = junk_group.sub("", text).strip()

    # Külön kezeli az olyan mintát, mint "(Video Official)".
    text = re.sub(
        r"\s*[\(\[]\s*(?:video|audio|lyrics?)\s+official\s*[\)\]]",
        "",
        text,
        flags=re.IGNORECASE
    ).strip()

    # Bitráta maradvány akkor is, ha nem zárójelben van.
    text = re.sub(
        r"\s*[-–—_]*\s*\d{2,4}\s*kbps\s*$",
        "",
        text,
        flags=re.IGNORECASE
    ).strip()

    # Sok letöltő "_ album/channel/extra" részt tesz a cím mögé.
    if " _ " in text:
        text = text.split(" _ ", 1)[0].strip()

    # Tipikus végi szöveges toldalékok.
    text = re.sub(
        r"\s*[-–—]\s*"
        r"(?:official\s*)?(?:music\s*)?"
        r"(?:video|audio|lyrics?)\s*$",
        "",
        text,
        flags=re.IGNORECASE
    ).strip()

    # FONTOS FIX:
    # Magányos / hibás zárójelek és szögletes zárójelek leszedése a cím elejéről/végéről.
    # Pl. "Szálljon a Dal]" vagy "[Szálljon a Dal".
    text = re.sub(r"^[\[\]\(\)\{\}]+", "", text).strip()
    text = re.sub(r"[\[\]\(\)\{\}]+$", "", text).strip()

    # Maradék felesleges írásjelek a széleken.
    text = text.strip(" \t\r\n-_–—|:;,.!~")

    text = re.sub(r"\s{2,}", " ", text).strip()
    return text


def _clean_download_artist(text):
    """
    Előadónév normalizálása.
    FloyyMenor FT Cris MJ -> FloyyMenor feat. Cris MJ
    """
    text = str(text or "").strip()

    text = re.sub(
        r"\s+(?:ft\.?|feat\.?|featuring)\s+",
        " feat. ",
        text,
        flags=re.IGNORECASE
    )

    text = re.sub(r"\s{2,}", " ", text).strip()
    return text


def _parse_artist_title_from_filename(filename):
    """
    Kezeli ezeket is:
    Artist - Title
    Artist – Title
    Artist — Title
    """
    base = os.path.splitext(
        os.path.basename(str(filename))
    )[0].strip()

    # Első olyan elválasztó, amely körül szóköz van.
    match = re.match(
        r"^\s*(.+?)\s+[-–—]\s+(.+?)\s*$",
        base
    )

    if match:
        artist = _clean_download_artist(
            match.group(1)
        )
        title = _clean_download_title(
            match.group(2)
        )
        return artist, title

    return "", _clean_download_title(base)


def _clean_downloaded_filename(filename):
    """
    Új letöltéseknél tisztább fájlnevet ad.
    A kiterjesztést megtartja.
    """
    filename = os.path.basename(
        str(filename or "")
    )

    base, ext = os.path.splitext(filename)
    artist, title = _parse_artist_title_from_filename(base)

    if artist and title:
        clean_base = f"{artist} - {title}"
    else:
        clean_base = _clean_download_title(base)

    clean_base = _safe_filename(clean_base)

    return clean_base + ext.lower()



def read_track_metadata(path):
    filename = os.path.splitext(os.path.basename(path))[0]
    artist = "Ismeretlen előadó"
    album = "Ismeretlen album"
    title = filename
    year = ""
    genre = ""
    track_no = 9999

    if MutagenFile is not None:
        try:
            audio = MutagenFile(path, easy=True)

            if audio is not None:
                tags = audio.tags

                artist = first_tag(
                    tags,
                    ["artist", "albumartist"],
                    artist
                )

                album = first_tag(
                    tags,
                    ["album"],
                    album
                )

                title = first_tag(
                    tags,
                    ["title"],
                    title
                )

                year = first_tag(
                    tags,
                    ["date", "year"],
                    ""
                )

                genre = first_tag(
                    tags,
                    ["genre"],
                    ""
                )

                raw_track = first_tag(
                    tags,
                    ["tracknumber"],
                    ""
                )

                m = re.match(
                    r"(\d+)",
                    raw_track
                )

                if m:
                    track_no = int(
                        m.group(1)
                    )

        except Exception:
            pass

    file_artist, file_title = _parse_artist_title_from_filename(
        filename
    )

    if (
        artist.casefold()
        in {
            "ismeretlen előadó",
            "ismeretlen eloado",
            "unknown artist",
            ""
        }
        and file_artist
    ):
        artist = file_artist

    raw_title = str(title or "").strip()

    if (
        not raw_title
        or raw_title == filename
        or "(video" in raw_title.casefold()
        or "(official" in raw_title.casefold()
        or "kbps" in raw_title.casefold()
        or " _ " in raw_title
    ):
        title = file_title
    else:
        title = _clean_download_title(
            raw_title
        )

    artist = _clean_download_artist(
        artist
    )

    return {
        "path": path,
        "filename": os.path.basename(path),
        "artist": artist,
        "album": album,
        "title": title,
        "year": year,
        "genre": genre,
        "track_no": track_no,
    }


def scan_library():
    global library

    library = []

    if not os.path.isdir(
        MUSIC_FOLDER
    ):
        return

    # Belső JustMusic! mappák, amelyeket SOHA nem szabad
    # zeneként beolvasni. Az EQ cache például MP3 fájlokat tartalmaz,
    # ezért korábban a SHA1/hash nevű cache fájlok megjelentek dalokként.
    internal_folders = {
        os.path.abspath(
            EQ_CACHE
        ),
        os.path.abspath(
            COVER_CACHE
        ),
        os.path.abspath(
            CUSTOM_COVER_FOLDER
        ),
    }

    for root_dir, dirs, files in os.walk(
        MUSIC_FOLDER,
        topdown=True
    ):
        root_abs = os.path.abspath(
            root_dir
        )

        # Rejtett / belső mappák kihagyása már bejárás előtt.
        dirs[:] = [
            dirname
            for dirname in dirs
            if (
                not dirname.startswith(".")
                and os.path.abspath(
                    os.path.join(
                        root_dir,
                        dirname
                    )
                ) not in internal_folders
            )
        ]

        # Extra védelem, ha mégis belső mappába jutnánk.
        if (
            root_abs in internal_folders
            or any(
                root_abs.startswith(
                    folder + os.sep
                )
                for folder in internal_folders
            )
        ):
            continue

        for filename in files:
            # Rejtett / ideiglenes fájlok kihagyása.
            if (
                filename.startswith(".")
                or filename.endswith(".part")
                or filename.endswith(".tmp")
            ):
                continue

            if filename.lower().endswith(
                SUPPORTED_AUDIO
            ):
                path = os.path.join(
                    root_dir,
                    filename
                )

                library.append(
                    read_track_metadata(
                        path
                    )
                )

    library.sort(
        key=lambda x: (
            x["artist"].lower(),
            x["album"].lower(),
            x["track_no"],
            x["title"].lower()
        )
    )


def load_favorites():
    global favorites
    favorites = set()
    try:
        with open(FAVORITES_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)
        favorites = set(data if isinstance(data, list) else [])
    except Exception:
        pass


def save_favorites():
    try:
        with open(FAVORITES_FILE, "w", encoding="utf-8") as f:
            json.dump(sorted(favorites), f, ensure_ascii=False, indent=2)
    except Exception as error:
        print("KEDVENCEK MENTESI HIBA:", error)


def artists():
    return sorted({t["artist"] for t in library}, key=str.lower)


def albums():
    return sorted({(t["artist"], t["album"]) for t in library}, key=lambda x: (x[0].lower(), x[1].lower()))


def albums_for_artist(artist):
    return sorted({t["album"] for t in library if t["artist"] == artist}, key=str.lower)


def tracks_for_artist_album(artist, album):
    tracks = [t for t in library if t["artist"] == artist and t["album"] == album]
    return sorted(tracks, key=lambda x: (x["track_no"], x["title"].lower()))


def tracks_for_artist(artist):
    tracks = [t for t in library if t["artist"] == artist]
    return sorted(tracks, key=lambda x: (x["album"].lower(), x["track_no"], x["title"].lower()))


def album_tracks_all(artist, album):
    return tracks_for_artist_album(artist, album)


def favorite_tracks():
    return [t for t in library if t["path"] in favorites]



