# METAADAT + BORITO SZERKESZTO
# =========================================================

def _custom_cover_base(track_path):
    digest = hashlib.sha1(
        str(track_path).encode(
            "utf-8",
            errors="replace"
        )
    ).hexdigest()

    return os.path.join(
        CUSTOM_COVER_FOLDER,
        digest
    )


def custom_cover_path(track_path):
    base = _custom_cover_base(
        track_path
    )

    for ext in (
        ".jpg",
        ".jpeg",
        ".png",
        ".webp"
    ):
        path = base + ext

        if os.path.isfile(
            path
        ):
            return path

    return None


def remove_custom_cover(track_path):
    base = _custom_cover_base(
        track_path
    )

    removed = False

    for ext in (
        ".jpg",
        ".jpeg",
        ".png",
        ".webp"
    ):
        path = base + ext

        if os.path.isfile(
            path
        ):
            try:
                os.remove(
                    path
                )
                removed = True
            except Exception:
                pass

    return removed


def save_custom_cover(
    track_path,
    source_image
):
    if Image is None:
        raise RuntimeError(
            "A borító szerkesztéshez Pillow szükséges."
        )

    os.makedirs(
        CUSTOM_COVER_FOLDER,
        exist_ok=True
    )

    remove_custom_cover(
        track_path
    )

    destination = (
        _custom_cover_base(
            track_path
        )
        + ".jpg"
    )

    image = Image.open(
        source_image
    ).convert(
        "RGB"
    )

    image.thumbnail(
        (1400, 1400),
        Image.LANCZOS
    )

    image.save(
        destination,
        "JPEG",
        quality=92,
        optimize=True
    )

    return destination


def _write_track_metadata(
    track,
    title,
    artist,
    album,
    track_number,
    year,
    genre
):
    if MutagenFile is None:
        raise RuntimeError(
            "A metaadat szerkesztéshez a mutagen csomag szükséges."
        )

    path = track["path"]

    audio = MutagenFile(
        path,
        easy=True
    )

    if audio is None:
        raise RuntimeError(
            "Ezt a fájltípust a Mutagen nem tudta megnyitni."
        )

    if audio.tags is None:
        try:
            audio.add_tags()
        except Exception:
            pass

    def set_tag(
        key,
        value
    ):
        value = str(
            value or ""
        ).strip()

        try:
            if value:
                audio[key] = [
                    value
                ]
            else:
                try:
                    del audio[key]
                except Exception:
                    pass
        except Exception as error:
            raise RuntimeError(
                f'Nem írható ez a mező: {key} ({error})'
            )

    set_tag(
        "title",
        title
    )

    set_tag(
        "artist",
        artist
    )

    set_tag(
        "album",
        album
    )

    set_tag(
        "genre",
        genre
    )

    set_tag(
        "date",
        year
    )

    track_text = str(
        track_number or ""
    ).strip()

    if track_text:
        match = re.match(
            r"(\d+)",
            track_text
        )

        if not match:
            raise RuntimeError(
                "A sorszám csak szám lehet."
            )

        set_tag(
            "tracknumber",
            match.group(1)
        )
    else:
        set_tag(
            "tracknumber",
            ""
        )

    audio.save()


def _sync_track_after_metadata_edit(
    path
):
    global queued_current

    fresh = read_track_metadata(
        path
    )

    # Fő könyvtár
    for index, item in enumerate(
        library
    ):
        if item.get("path") == path:
            library[index] = dict(
                fresh
            )

    # Aktuális lejátszási lista
    for index, item in enumerate(
        current_library
    ):
        if item.get("path") == path:
            current_library[index] = dict(
                fresh
            )

    # Queue
    for index, item in enumerate(
        play_queue
    ):
        if item.get("path") == path:
            play_queue[index] = dict(
                fresh
            )

    # Éppen queue-ból játszott szám
    if (
        queued_current is not None
        and queued_current.get("path") == path
    ):
        queued_current.update(
            fresh
        )

    return fresh


