def find_cover_source(track):
    # 1. JustMusic! saját, dalonkénti borító override.
    custom = custom_cover_path(
        track["path"]
    )

    if custom:
        return custom

    # 2. Mappaborító.
    folder = os.path.dirname(track["path"])
    for name in ("cover.jpg", "cover.jpeg", "cover.png", "folder.jpg", "folder.png", "front.jpg", "front.png"):
        p = os.path.join(folder, name)
        if os.path.isfile(p):
            return p

    if MutagenFile is None:
        return None

    try:
        audio = MutagenFile(track["path"])
        if audio is None:
            return None

        # MP3 / ID3 APIC
        if hasattr(audio, "tags") and audio.tags:
            try:
                for key in audio.tags.keys():
                    if str(key).startswith("APIC"):
                        apic = audio.tags[key]
                        if getattr(apic, "data", None):
                            digest = hashlib.md5(track["path"].encode("utf-8")).hexdigest()
                            ext = ".jpg"
                            mime = getattr(apic, "mime", "")
                            if "png" in mime:
                                ext = ".png"
                            out = os.path.join(COVER_CACHE, digest + ext)
                            if not os.path.exists(out):
                                with open(out, "wb") as f:
                                    f.write(apic.data)
                            return out
            except Exception:
                pass

        # FLAC / MP4 pictures
        pictures = getattr(audio, "pictures", None)
        if pictures:
            pic = pictures[0]
            digest = hashlib.md5(track["path"].encode("utf-8")).hexdigest()
            ext = ".png" if "png" in getattr(pic, "mime", "") else ".jpg"
            out = os.path.join(COVER_CACHE, digest + ext)
            if not os.path.exists(out):
                with open(out, "wb") as f:
                    f.write(pic.data)
            return out

    except Exception:
        pass

    return None


def make_placeholder(key, size=(120, 120)):
    if Image is None or ImageTk is None:
        return None
    img = Image.new("RGB", size, JM_PANEL_2)
    if ImageDraw:
        d = ImageDraw.Draw(img)
        d.rectangle((8, 8, size[0] - 8, size[1] - 8), outline="#444444", width=2)
        d.text((size[0] // 2 - 6, size[1] // 2 - 8), "♫", fill=JM_MUTED)
    return ImageTk.PhotoImage(img)


def get_cover(track, size=(120, 120)):
    if Image is None or ImageTk is None:
        return None
    source = find_cover_source(track)
    if source:
        try:
            img = Image.open(source).convert("RGB")
            img.thumbnail(size, Image.LANCZOS)
            canvas_img = Image.new("RGB", size, JM_PANEL)
            x = (size[0] - img.width) // 2
            y = (size[1] - img.height) // 2
            canvas_img.paste(img, (x, y))
            return ImageTk.PhotoImage(canvas_img)
        except Exception:
            pass
    return make_placeholder(track["album"], size)


def cover_for_album(artist, album, size=(140, 140)):
    tracks = tracks_for_artist_album(artist, album)
    return get_cover(tracks[0], size) if tracks else None


