SMART_PLAYLIST_INFO = {
    "top": {
        "title": "🔥 Top dalok",
        "description": "A legtöbbet hallgatott zenéid automatikusan.",
    },
    "recent": {
        "title": "🕘 Nemrég hallgatott",
        "description": "A legutóbb elindított zenék, ismétlés nélkül.",
    },
    "added": {
        "title": "✨ Nemrég hozzáadott",
        "description": "A legfrissebben bekerült zenék a könyvtárból.",
    },
    "unplayed": {
        "title": "🌙 Még nem hallgatott",
        "description": "Zenék, amelyeket a JustMusic! szerint még nem indítottál el.",
    },
    "forgotten": {
        "title": "💎 Elfeledett kedvencek",
        "description": "Régebben hallgatott, de mostanában háttérbe szorult zenék.",
    },
    "favorites": {
        "title": "🩵 Kedvencek Mix",
        "description": "A kedvenceid egy automatikus listában.",
    },
}


def _track_stats_for(track):
    return listening_stats.get(
        track.get(
            "path"
        ),
        {}
    )


def smart_playlist_tracks(kind):
    kind = str(
        kind
    ).lower()

    if kind == "top":
        return sorted(
            library,
            key=lambda track: (
                int(
                    _track_stats_for(
                        track
                    ).get(
                        "play_count",
                        0
                    )
                ),
                float(
                    _track_stats_for(
                        track
                    ).get(
                        "listened_seconds",
                        0.0
                    )
                ),
            ),
            reverse=True
        )[:50]

    if kind == "recent":
        result = []
        seen = set()

        for item in reversed(
            listening_history
        ):
            path = item.get(
                "path"
            )

            if not path or path in seen:
                continue

            track = track_by_path(
                path
            )

            if track is None:
                continue

            seen.add(
                path
            )

            result.append(
                track
            )

            if len(result) >= 50:
                break

        return result

    if kind == "added":
        def modified_time(track):
            try:
                return os.path.getmtime(
                    track["path"]
                )
            except Exception:
                return 0.0

        return sorted(
            library,
            key=modified_time,
            reverse=True
        )[:50]

    if kind == "unplayed":
        return sorted(
            [
                track
                for track in library
                if int(
                    _track_stats_for(
                        track
                    ).get(
                        "play_count",
                        0
                    )
                ) == 0
            ],
            key=lambda track: (
                track.get(
                    "artist",
                    ""
                ).casefold(),
                track.get(
                    "album",
                    ""
                ).casefold(),
                track.get(
                    "title",
                    ""
                ).casefold(),
            )
        )

    if kind == "forgotten":
        candidates = []

        for track in library:
            stats = _track_stats_for(
                track
            )

            plays = int(
                stats.get(
                    "play_count",
                    0
                )
            )

            last_played = stats.get(
                "last_played"
            )

            if plays <= 0 or not last_played:
                continue

            try:
                timestamp = datetime.fromisoformat(
                    str(
                        last_played
                    )
                ).timestamp()
            except Exception:
                timestamp = 0.0

            candidates.append(
                (
                    timestamp,
                    -plays,
                    track
                )
            )

        candidates.sort(
            key=lambda item: (
                item[0],
                item[1]
            )
        )

        return [
            item[2]
            for item in candidates[:40]
        ]

    if kind == "favorites":
        return sorted(
            favorite_tracks(),
            key=lambda track: (
                -int(
                    _track_stats_for(
                        track
                    ).get(
                        "play_count",
                        0
                    )
                ),
                track.get(
                    "artist",
                    ""
                ).casefold(),
                track.get(
                    "title",
                    ""
                ).casefold(),
            )
        )

    return []


def show_smart_playlist(kind):
    info = SMART_PLAYLIST_INFO.get(
        kind
    )

    if not info:
        return

    tracks = smart_playlist_tracks(
        kind
    )

    set_library_view(
        tracks,
        info["title"],
        f"smart:{kind}"
    )


