def refresh_current_view():
    if current_view == "artists":
        show_artists()
    elif current_view == "albums":
        show_all_albums()
    elif current_view == "favorites":
        set_library_view(favorite_tracks(), "Kedvencek", "favorites")
    elif current_view == "tracks":
        title = page_title.cget("text")
        set_library_view(current_library, title, "tracks")
    elif current_view == "search":
        perform_search(search_var.get())
    elif current_view == "playlist":
        # A playlist név a lapcímből jön vissza.
        title = str(page_title.cget("text"))
        prefix = "Playlist — "

        if title.startswith(prefix):
            show_playlist_tracks(
                title[len(prefix):]
            )
        else:
            show_home()
    elif current_view == "stats":
        show_stats()
    elif current_view == "smart":
        show_smart_playlists()
    elif str(current_view).startswith("smart:"):
        show_smart_playlist(
            str(current_view).split(
                ":",
                1
            )[1]
        )
    else:
        show_home()


def render_artist_cards(artist_names):
    """Spotify-szerű előadó-kártyák az Előadók oldalon."""
    if not artist_names:
        tk.Label(
            song_list_frame,
            text="Még nincs előadó a zenetárban.",
            font=("Arial", 15),
            fg=JM_MUTED,
            bg=JM_BG
        ).pack(pady=40)
        return

    grid = tk.Frame(
        song_list_frame,
        bg=JM_BG_2
    )
    grid.pack(
        fill="both",
        expand=True,
        padx=15,
        pady=(8, 20)
    )

    install_party_background(
        grid,
        brightness=0.72,
        blur=0.6,
        saturation=1.10
    )

    columns = 4
    for index, artist in enumerate(artist_names):
        count_albums = len(albums_for_artist(artist))
        count_tracks = len(tracks_for_artist(artist))

        card = tk.Frame(
            grid,
            bg=JM_CARD,
            width=190,
            height=225,
            cursor="hand2",
            highlightthickness=1,
            highlightbackground=JM_BORDER
        )
        card.grid(
            row=index // columns,
            column=index % columns,
            padx=8,
            pady=8,
            sticky="nsew"
        )
        card.grid_propagate(False)

        # Kör alakú előadó-avatar helyett egy nagy monogramos jelvény.
        # Később ezt egyszerűen lecserélhetjük valódi előadóképre.
        avatar = tk.Canvas(
            card,
            width=126,
            height=126,
            bg=JM_CARD,
            highlightthickness=0,
            cursor="hand2"
        )
        avatar.pack(pady=(14, 8))
        avatar.create_oval(8, 8, 118, 118, fill="#112A45", outline=JM_CYAN_DARK, width=2)
        initials = "".join(word[0] for word in artist.split()[:2] if word).upper() or "♪"
        avatar.create_text(63, 63, text=initials, fill=JM_TEXT, font=("Arial", 28, "bold"))

        name_label = tk.Label(
            card,
            text=artist,
            font=("Arial", 12, "bold"),
            fg=JM_TEXT,
            bg=JM_CARD,
            wraplength=165,
            cursor="hand2"
        )
        name_label.pack(padx=10, pady=(0, 4))

        info_label = tk.Label(
            card,
            text=f"{count_albums} album • {count_tracks} dal",
            font=("Arial", 9),
            fg=JM_MUTED,
            bg=JM_CARD,
            cursor="hand2"
        )
        info_label.pack(padx=10)

        def open_artist(event=None, a=artist):
            show_albums(a)

        def hover_on(event=None, c=card, a=avatar, n=name_label, i=info_label):
            c.config(
                bg=JM_CARD_HOVER,
                highlightbackground=JM_CYAN
            )
            a.config(bg=JM_CARD_HOVER)
            n.config(bg=JM_CARD_HOVER)
            i.config(bg=JM_CARD_HOVER)

        def hover_off(event=None, c=card, a=avatar, n=name_label, i=info_label):
            c.config(
                bg=JM_CARD,
                highlightbackground=JM_BORDER
            )
            a.config(bg=JM_CARD)
            n.config(bg=JM_CARD)
            i.config(bg=JM_CARD)

        for widget in (card, avatar, name_label, info_label):
            widget.bind("<Button-1>", open_artist)
            widget.bind("<Enter>", hover_on)
            widget.bind("<Leave>", hover_off)

    for col in range(columns):
        grid.grid_columnconfigure(col, weight=1)


def show_artists():
    global current_view, current_artist, current_album

    current_view = "artists"
    current_artist = None
    current_album = None

    clear_frame(
        song_list_frame
    )

    page_title.config(
        text="Előadók"
    )

    try:
        page_subtitle.config(
            text="Kattints egy előadóra az albumjai megnyitásához."
        )
    except Exception:
        pass

    # -----------------------------------------------------
    # Made In Hungary — Neon Glass banner
    # -----------------------------------------------------
    banner = tk.Canvas(
        song_list_frame,
        height=132,
        bg=JM_PANEL,
        highlightthickness=1,
        highlightbackground=JM_CYAN_DARK,
        borderwidth=0
    )

    banner.pack(
        fill="x",
        padx=20,
        pady=(10, 14)
    )

    def redraw_banner(event=None):
        banner.delete(
            "all"
        )

        width = max(
            banner.winfo_width(),
            700
        )

        height = max(
            banner.winfo_height(),
            132
        )

        # Pontosan ugyanaz a koncertkép, mint a teljes háttérben.
        photo = _jm_make_party_photo(
            width,
            height,
            brightness=0.82,
            blur=0.0,
            saturation=1.08
        )

        banner._jm_party_photo = photo

        if photo is not None:
            banner.create_image(
                0,
                0,
                anchor="nw",
                image=photo
            )
        else:
            banner.create_rectangle(
                0,
                0,
                width,
                height,
                fill=JM_PANEL,
                outline=""
            )

        # Bal oldalon sötét overlay-hatás Canvas rétegekkel,
        # hogy a felirat biztosan olvasható legyen.
        overlay_width = min(
            width * 0.64,
            650
        )

        overlay_steps = 18

        for index in range(
            overlay_steps
        ):
            x1 = (
                index
                * overlay_width
                / overlay_steps
            )
            x2 = (
                (index + 1)
                * overlay_width
                / overlay_steps
            )

            # Tkinter Canvas nem tud alpha-t, ezért fokozatos
            # sötétkék gradienttel utánozzuk.
            t = (
                index
                / max(
                    overlay_steps - 1,
                    1
                )
            )

            r = int(4 + 4 * t)
            g = int(14 + 14 * t)
            b = int(27 + 26 * t)

            color = f"#{r:02x}{g:02x}{b:02x}"

            banner.create_rectangle(
                x1,
                0,
                x2 + 1,
                height,
                fill=color,
                outline=""
            )

        banner.create_rectangle(
            0,
            height - 3,
            width,
            height,
            fill=JM_CYAN,
            outline=""
        )

        banner.create_text(
            24,
            27,
            anchor="w",
            text="HU",
            fill=JM_CYAN_BRIGHT,
            font=("Segoe UI", 10, "bold")
        )

        banner.create_text(
            24,
            58,
            anchor="w",
            text="MADE IN HUNGARY",
            fill=JM_TEXT,
            font=("Segoe UI", 23, "bold")
        )

        banner.create_text(
            24,
            91,
            anchor="w",
            text="Szabó Zoltán",
            fill=JM_TEXT_2,
            font=("Segoe UI", 11, "bold")
        )

        banner.create_text(
            24,
            113,
            anchor="w",
            text="IG: ZS420LLER",
            fill=JM_CYAN_BRIGHT,
            font=("Segoe UI", 9, "bold")
        )

        banner.create_text(
            width - 225,
            32,
            anchor="w",
            text="Hungarian",
            fill=JM_CYAN_BRIGHT,
            font=("Segoe Script", 13, "italic")
        )

        banner.create_text(
            width - 195,
            55,
            anchor="w",
            text="Music Lives On",
            fill=JM_TEXT,
            font=("Segoe Script", 11, "italic")
        )

    banner.bind(
        "<Configure>",
        redraw_banner
    )

    banner.bind(
        "<Button-1>",
        lambda event:
            webbrowser.open(
                "https://www.instagram.com/zs420ller/"
            )
    )

    redraw_banner()

    render_artist_cards(
        artists()
    )

    refresh_nav_active()



