def perform_search(query):
    global current_view
    query = query.strip().lower()
    current_view = "search"
    clear_frame(song_list_frame)
    if not query:
        page_title.config(text="Keresés")
        tk.Label(song_list_frame, text="Írj be előadót, albumot vagy dalt.", font=("Arial", 16), fg=JM_MUTED, bg=JM_BG).pack(pady=30)
        return
    results = [t for t in library if query in t["title"].lower() or query in t["artist"].lower() or query in t["album"].lower()]
    page_title.config(text=f"Keresés: {search_var.get()}")
    render_track_list(results)


def search_key(event=None):
    global search_after_id
    if search_after_id is not None:
        root.after_cancel(search_after_id)
    search_after_id = root.after(250, lambda: perform_search(search_var.get()))





# =========================================================
# CROSSFADE / ALBUM MIX
# =========================================================

def _sync_legacy_crossfade_seconds():
    global crossfade_seconds

    crossfade_seconds = max(
        0.0,
        float(mix_fade_out_seconds)
        + float(mix_fade_in_seconds)
    )


def update_mix_ui():
    _sync_legacy_crossfade_seconds()

    try:
        if mix_gapless_enabled:
            mix_button.config(
                text="MIX GAP",
                fg=JM_CYAN
            )
        elif crossfade_enabled:
            mix_button.config(
                text=(
                    f"MIX "
                    f"{mix_fade_out_seconds:.1f}/"
                    f"{mix_fade_in_seconds:.1f}"
                ),
                fg=JM_CYAN
            )
        else:
            mix_button.config(
                text="MIX",
                fg=JM_TEXT
            )
    except Exception:
        pass

    try:
        if (
            mix_status_label is not None
            and mix_status_label.winfo_exists()
        ):
            if mix_gapless_enabled:
                status = "GAPLESS • azonnali dalváltás"
            elif crossfade_enabled:
                status = (
                    "MIX: BE  •  "
                    f"Fade Out {mix_fade_out_seconds:.1f}s  •  "
                    f"Fade In {mix_fade_in_seconds:.1f}s"
                )
            else:
                status = "MIX: KI"

            mix_status_label.config(
                text=status,
                fg=(
                    JM_CYAN
                    if (
                        crossfade_enabled
                        or mix_gapless_enabled
                    )
                    else JM_MUTED
                )
            )
    except Exception:
        pass

    try:
        if (
            mix_seconds_label is not None
            and mix_seconds_label.winfo_exists()
        ):
            mix_seconds_label.config(
                text=(
                    f"{mix_fade_out_seconds + mix_fade_in_seconds:.1f} mp összesen"
                )
            )
    except Exception:
        pass

    try:
        if (
            mix_fade_out_label is not None
            and mix_fade_out_label.winfo_exists()
        ):
            mix_fade_out_label.config(
                text=f"{mix_fade_out_seconds:.1f} mp"
            )
    except Exception:
        pass

    try:
        if (
            mix_fade_in_label is not None
            and mix_fade_in_label.winfo_exists()
        ):
            mix_fade_in_label.config(
                text=f"{mix_fade_in_seconds:.1f} mp"
            )
    except Exception:
        pass

    try:
        if (
            mix_mode_label is not None
            and mix_mode_label.winfo_exists()
        ):
            mode_parts = []

            mode_parts.append(
                "AUTO: BE"
                if mix_auto_transition_enabled
                else "AUTO: KI"
            )

            mode_parts.append(
                "KÉZI NEXT: BE"
                if mix_manual_transition_enabled
                else "KÉZI NEXT: KI"
            )

            if mix_dj_mode_enabled:
                mode_parts.append(
                    "DJ MODE"
                )

            mix_mode_label.config(
                text="   •   ".join(
                    mode_parts
                )
            )
    except Exception:
        pass

    # Toggle gombok színei.
    button_states = (
        (
            mix_auto_button,
            mix_auto_transition_enabled
        ),
        (
            mix_manual_button,
            mix_manual_transition_enabled
        ),
        (
            mix_gapless_button,
            mix_gapless_enabled
        ),
        (
            mix_dj_button,
            mix_dj_mode_enabled
        ),
    )

    for button, enabled in button_states:
        try:
            if (
                button is not None
                and button.winfo_exists()
            ):
                button.config(
                    fg=(
                        JM_CYAN
                        if enabled
                        else JM_TEXT_2
                    )
                )
        except Exception:
            pass

    update_now_playing_progress()


def set_crossfade_enabled(enabled):
    global crossfade_enabled
    global mix_gapless_enabled

    crossfade_enabled = bool(
        enabled
    )

    if crossfade_enabled:
        mix_gapless_enabled = False

    update_mix_ui()
    schedule_save_settings()


def toggle_crossfade():
    set_crossfade_enabled(
        not crossfade_enabled
    )


def set_mix_fade_out(value):
    global mix_fade_out_seconds

    try:
        seconds = float(
            value
        )
    except Exception:
        seconds = 1.5

    mix_fade_out_seconds = max(
        0.0,
        min(
            10.0,
            seconds
        )
    )

    update_mix_ui()
    schedule_save_settings()


def set_mix_fade_in(value):
    global mix_fade_in_seconds

    try:
        seconds = float(
            value
        )
    except Exception:
        seconds = 1.5

    mix_fade_in_seconds = max(
        0.0,
        min(
            10.0,
            seconds
        )
    )

    update_mix_ui()
    schedule_save_settings()


def set_crossfade_seconds(value):
    """
    Legacy kompatibilitás:
    a megadott teljes időt felezzük Fade Out / Fade In között.
    """
    try:
        seconds = float(
            value
        )
    except Exception:
        seconds = 3.0

    seconds = max(
        0.0,
        min(
            20.0,
            seconds
        )
    )

    half = seconds / 2.0

    set_mix_fade_out(
        half
    )

    set_mix_fade_in(
        seconds - half
    )


def toggle_mix_auto():
    global mix_auto_transition_enabled

    mix_auto_transition_enabled = (
        not mix_auto_transition_enabled
    )

    update_mix_ui()
    schedule_save_settings()


def toggle_mix_manual():
    global mix_manual_transition_enabled

    mix_manual_transition_enabled = (
        not mix_manual_transition_enabled
    )

    update_mix_ui()
    schedule_save_settings()


def toggle_gapless():
    global mix_gapless_enabled
    global crossfade_enabled

    mix_gapless_enabled = (
        not mix_gapless_enabled
    )

    if mix_gapless_enabled:
        crossfade_enabled = False

    update_mix_ui()
    schedule_save_settings()


def set_dj_mode(enabled):
    global mix_dj_mode_enabled
    global repeat_mode

    mix_dj_mode_enabled = bool(
        enabled
    )

    if mix_dj_mode_enabled:
        repeat_mode = "all"

        set_shuffle_state(
            True
        )

        set_crossfade_enabled(
            True
        )

        # DJ alapérték.
        set_mix_fade_out(
            2.0
        )

        set_mix_fade_in(
            2.5
        )

    refresh_playback_mode_buttons()
    update_mix_ui()
    schedule_save_settings()


def toggle_dj_mode():
    set_dj_mode(
        not mix_dj_mode_enabled
    )


def apply_mix_preset(name):
    global mix_gapless_enabled
    global crossfade_enabled
    global mix_auto_transition_enabled
    global mix_manual_transition_enabled
    global mix_dj_mode_enabled

    preset = str(
        name
    ).lower()

    mix_dj_mode_enabled = False

    if preset == "quick":
        mix_gapless_enabled = False
        crossfade_enabled = True
        mix_auto_transition_enabled = True
        mix_manual_transition_enabled = True
        set_mix_fade_out(
            0.5
        )
        set_mix_fade_in(
            0.8
        )

    elif preset == "smooth":
        mix_gapless_enabled = False
        crossfade_enabled = True
        mix_auto_transition_enabled = True
        mix_manual_transition_enabled = True
        set_mix_fade_out(
            2.0
        )
        set_mix_fade_in(
            2.5
        )

    elif preset == "radio":
        mix_gapless_enabled = False
        crossfade_enabled = True
        mix_auto_transition_enabled = True
        mix_manual_transition_enabled = True
        set_mix_fade_out(
            1.0
        )
        set_mix_fade_in(
            1.2
        )

    elif preset == "cinematic":
        mix_gapless_enabled = False
        crossfade_enabled = True
        mix_auto_transition_enabled = True
        mix_manual_transition_enabled = True
        set_mix_fade_out(
            4.0
        )
        set_mix_fade_in(
            4.0
        )

    elif preset == "gapless":
        mix_gapless_enabled = True
        crossfade_enabled = False
        mix_auto_transition_enabled = False
        mix_manual_transition_enabled = False
        set_mix_fade_out(
            0.0
        )
        set_mix_fade_in(
            0.0
        )

    elif preset == "dj":
        mix_gapless_enabled = False
        crossfade_enabled = True
        mix_auto_transition_enabled = True
        mix_manual_transition_enabled = True
        mix_dj_mode_enabled = True

        set_mix_fade_out(
            2.0
        )
        set_mix_fade_in(
            2.5
        )

        global repeat_mode
        repeat_mode = "all"

        set_shuffle_state(
            True
        )

        refresh_playback_mode_buttons()

    update_mix_ui()
    schedule_save_settings()


def cancel_pending_transition():
    global transition_in_progress
    global transition_after_id

    if transition_after_id is not None:
        try:
            root.after_cancel(
                transition_after_id
            )
        except Exception:
            pass

    transition_after_id = None
    transition_in_progress = False


def _transition_fade_parts():
    """
    Pygame egy streamet játszik, ezért ez soft mix:
    Fade Out -> következő dal -> Fade In.
    """

    out_ms = int(
        max(
            0.0,
            mix_fade_out_seconds
        )
        * 1000
    )

    in_ms = int(
        max(
            0.0,
            mix_fade_in_seconds
        )
        * 1000
    )

    return (
        out_ms,
        in_ms
    )


def _finish_next_transition(auto):
    global transition_in_progress
    global transition_after_id
    global next_play_fade_ms

    transition_after_id = None
    transition_in_progress = False

    _, in_ms = _transition_fade_parts()

    next_play_fade_ms = in_ms

    next_song(
        auto=auto,
        allow_crossfade=False
    )


def start_next_transition(auto=False):
    global transition_in_progress
    global transition_after_id

    if transition_in_progress:
        return

    # Gapless: nincs fade, azonnal következő.
    if mix_gapless_enabled:
        next_song(
            auto=auto,
            allow_crossfade=False
        )
        return

    if (
        not crossfade_enabled
        or not song_started
        or paused
    ):
        next_song(
            auto=auto,
            allow_crossfade=False
        )
        return

    out_ms, _ = _transition_fade_parts()

    if out_ms <= 0:
        next_song(
            auto=auto,
            allow_crossfade=False
        )
        return

    transition_in_progress = True

    try:
        pygame.mixer.music.fadeout(
            out_ms
        )
    except Exception:
        transition_in_progress = False

        next_song(
            auto=auto,
            allow_crossfade=False
        )
        return

    transition_after_id = root.after(
        out_ms,
        lambda:
            _finish_next_transition(
                auto
            )
    )


def restart_current_with_fade():
    global next_play_fade_ms

    if not song_started:
        return

    _, in_ms = _transition_fade_parts()

    next_play_fade_ms = (
        in_ms
        if in_ms > 0
        else 1000
    )

    play_song(
        start_position=0.0
    )


def fade_out_current():
    if not song_started:
        return

    out_ms, _ = _transition_fade_parts()

    if out_ms <= 0:
        out_ms = 1000

    try:
        pygame.mixer.music.fadeout(
            out_ms
        )
    except Exception as error:
        print(
            "MANUAL FADE OUT HIBA:",
            error
        )


