def _keyboard_focus_is_typing():
    try:
        focus = root.focus_get()

        return isinstance(
            focus,
            (
                tk.Entry,
                tk.Text,
                tk.Scale,
                tk.Spinbox
            )
        )
    except Exception:
        return False


def keyboard_space(event=None):
    if _keyboard_focus_is_typing():
        return

    toggle_pause()
    return "break"


def keyboard_seek_back(event=None):
    if _keyboard_focus_is_typing():
        return

    seek_relative(
        -10
    )
    return "break"


def keyboard_seek_forward(event=None):
    if _keyboard_focus_is_typing():
        return

    seek_relative(
        10
    )
    return "break"


def keyboard_previous(event=None):
    if _keyboard_focus_is_typing():
        return

    previous_song()
    return "break"


def keyboard_next(event=None):
    if _keyboard_focus_is_typing():
        return

    next_song()
    return "break"


def keyboard_mute(event=None):
    if _keyboard_focus_is_typing():
        return

    toggle_mute()
    return "break"


def keyboard_now_playing(event=None):
    if _keyboard_focus_is_typing():
        return

    show_now_playing_fullscreen()
    return "break"


def keyboard_lyrics(event=None):
    if _keyboard_focus_is_typing():
        return

    open_fullscreen_lyrics()
    return "break"


def keyboard_sleep(event=None):
    if _keyboard_focus_is_typing():
        return

    open_sleep_timer_window()
    return "break"




# =========================================================
# MINI PLAYER PRO
# =========================================================

def mini_seek_start(event=None):
    global mini_seeking
    mini_seeking = True


def mini_seek_finish(event=None):
    global mini_seeking

    if (
        mini_progress is None
        or not song_started
    ):
        mini_seeking = False
        return

    try:
        target = float(
            mini_progress.get()
        )

        progress.set(
            target
        )

        finish_seek()

    except Exception as error:
        print(
            "MINI PLAYER TEKERÉSI HIBA:",
            error
        )

    mini_seeking = False


def mini_set_volume(value):
    try:
        value = max(
            0.0,
            min(
                100.0,
                float(value)
            )
        )

        volume.set(
            value
        )

    except Exception as error:
        print(
            "MINI PLAYER HANGERŐ HIBA:",
            error
        )


def mini_toggle_topmost():
    try:
        if (
            mini_player_window is not None
            and mini_player_window.winfo_exists()
        ):
            mini_player_window.attributes(
                "-topmost",
                bool(
                    mini_topmost_var.get()
                )
            )
    except Exception:
        pass


def mini_toggle_shuffle():
    toggle_shuffle()
    refresh_mini_player()


def mini_cycle_repeat():
    cycle_repeat_mode()
    refresh_mini_player()


def restore_full_justmusic():
    try:
        root.deiconify()
        root.lift()
        root.focus_force()
    except Exception:
        pass

    close_mini_player(
        restore_main=False
    )


def close_mini_player(
    restore_main=True
):
    global mini_player_window
    global mini_cover_label
    global mini_cover_ref
    global mini_title_label
    global mini_artist_label
    global mini_album_label
    global mini_time_label
    global mini_mode_label
    global mini_queue_label
    global mini_visualizer_canvas
    global mini_play_button
    global mini_shuffle_button
    global mini_repeat_button
    global mini_progress
    global mini_volume_scale
    global mini_topmost_var
    global mini_seeking

    if restore_main:
        try:
            root.deiconify()
            root.lift()
        except Exception:
            pass

    try:
        if (
            mini_player_window is not None
            and mini_player_window.winfo_exists()
        ):
            mini_player_window.destroy()
    except Exception:
        pass

    mini_player_window = None
    mini_cover_label = None
    mini_cover_ref = None
    mini_title_label = None
    mini_artist_label = None
    mini_album_label = None
    mini_time_label = None
    mini_mode_label = None
    mini_queue_label = None
    mini_visualizer_canvas = None
    mini_play_button = None
    mini_shuffle_button = None
    mini_repeat_button = None
    mini_progress = None
    mini_volume_scale = None
    mini_topmost_var = None
    mini_seeking = False


def _mini_repeat_text():
    if repeat_mode == "one":
        return JM_ICONS["repeat_one"]

    return JM_ICONS["repeat"]


def _mini_mode_text():
    shuffle_text = (
        "SHUFFLE BE"
        if shuffle_enabled
        else "SHUFFLE KI"
    )

    if repeat_mode == "all":
        repeat_text = "REPEAT ALL"
    elif repeat_mode == "one":
        repeat_text = "REPEAT ONE"
    else:
        repeat_text = "REPEAT KI"

    sleep_text = _sleep_timer_text()

    return (
        f"{shuffle_text}  •  "
        f"{repeat_text}  •  "
        f"{sleep_text}"
    )


def refresh_mini_player(
    current_seconds=None
):
    global mini_cover_ref

    try:
        if (
            mini_player_window is None
            or not mini_player_window.winfo_exists()
        ):
            return
    except Exception:
        return

    track = current_track()

    if track is None:
        try:
            mini_title_label.config(
                text="Nincs kiválasztott dal"
            )

            mini_artist_label.config(
                text="JustMusic!"
            )

            mini_album_label.config(
                text=""
            )

            mini_time_label.config(
                text="0:00 / 0:00"
            )

            mini_mode_label.config(
                text=_mini_mode_text()
            )

            mini_queue_label.config(
                text=f"SOR: {len(play_queue)}"
            )

            mini_play_button.config(
                text=JM_ICONS["play"]
            )

            mini_cover_label.config(
                image="",
                text="♫"
            )
        except Exception:
            pass

        return

    try:
        title = _clean_track_title_for_search(
            track.get(
                "title",
                ""
            )
        )

        mini_title_label.config(
            text=title
        )

        mini_artist_label.config(
            text=track.get(
                "artist",
                "Ismeretlen előadó"
            )
        )

        mini_album_label.config(
            text=track.get(
                "album",
                "Ismeretlen album"
            )
        )

    except Exception:
        pass

    try:
        cover = get_cover(
            track,
            (138, 138)
        )

        if cover:
            mini_cover_ref = cover

            mini_cover_label.config(
                image=cover,
                text=""
            )
        else:
            mini_cover_label.config(
                image="",
                text="♫"
            )

    except Exception:
        pass

    if current_seconds is None:
        current_seconds = (
            get_current_position()
            if song_started
            else 0.0
        )

    try:
        mini_time_label.config(
            text=(
                f"{format_time(current_seconds)}"
                "  /  "
                f"{format_time(song_length)}"
            )
        )
    except Exception:
        pass

    try:
        mini_play_button.config(
            text=(
                JM_ICONS["play"]
                if (
                    not song_started
                    or paused
                )
                else JM_ICONS["pause"]
            )
        )
    except Exception:
        pass

    try:
        mini_shuffle_button.config(
            fg=(
                JM_CYAN
                if shuffle_enabled
                else JM_TEXT
            )
        )

        mini_repeat_button.config(
            text=_mini_repeat_text(),
            fg=(
                JM_CYAN
                if repeat_mode != "off"
                else JM_TEXT
            )
        )

        mini_mode_label.config(
            text=_mini_mode_text()
        )

        mini_queue_label.config(
            text=f"SOR: {len(play_queue)}"
        )
    except Exception:
        pass

    try:
        if (
            mini_progress is not None
            and not mini_seeking
        ):
            mini_progress.config(
                to=max(
                    song_length,
                    1
                )
            )

            mini_progress.set(
                min(
                    current_seconds,
                    max(
                        song_length,
                        1
                    )
                )
            )
    except Exception:
        pass

    try:
        if mini_volume_scale is not None:
            current_vol = float(
                volume.get()
            )

            if abs(
                float(
                    mini_volume_scale.get()
                ) - current_vol
            ) > 0.5:
                mini_volume_scale.set(
                    current_vol
                )
    except Exception:
        pass


