def update_queue_button():
    """Frissíti a queue gombon a várakozó dalok számát."""
    try:
        queue_button.config(
            text=f'{JM_ICONS["queue"]} {len(play_queue)}'
        )
    except Exception:
        pass

    try:
        if (
            queue_count_label is not None
            and queue_count_label.winfo_exists()
        ):
            queue_count_label.config(
                text=f"{len(play_queue)} dal várakozik"
            )
    except Exception:
        pass


def add_to_queue(track):
    if not track:
        return

    play_queue.append(
        dict(track)
    )

    update_queue_button()
    refresh_queue_window()


def remove_from_queue(index):
    if 0 <= index < len(play_queue):
        play_queue.pop(index)

    update_queue_button()
    refresh_queue_window()


def move_queue_item(index, direction):
    new_index = index + direction

    if not (
        0 <= index < len(play_queue)
        and 0 <= new_index < len(play_queue)
    ):
        return

    play_queue[index], play_queue[new_index] = (
        play_queue[new_index],
        play_queue[index]
    )

    refresh_queue_window()


def clear_play_queue():
    play_queue.clear()
    update_queue_button()
    refresh_queue_window()


