def current_track():
    if queued_current is not None:
        return queued_current

    if 0 <= current_index < len(current_library):
        return current_library[current_index]

    return None


def normalize_name(text):
    text = os.path.splitext(os.path.basename(str(text)))[0]
    text = unicodedata.normalize("NFKD", text)
    text = "".join(ch for ch in text if not unicodedata.combining(ch))
    text = text.casefold()
    text = re.sub(r"[^a-z0-9]+", "", text)
    return text


def find_lyrics_file(song_path):
    """
    Minden dalhoz megprobalja automatikusan megtalalni a megfelelo .lrc fajlt.

    Keresesi sorrend:
    1. Ugyanabban a mappaban, ugyanazzal az alapnevvel.
    2. A fő JustMusic! zenei mappában, ugyanazzal az alapnevvel.
    3. Almappakban pontos fajlnevvel.
    4. Normalizalt nev alapjan (ekezet/szojel/space kulonbsegek mellett is).
    """

    song_path = str(song_path)
    base_name = os.path.splitext(os.path.basename(song_path))[0]
    song_dir = os.path.dirname(song_path)

    exact_candidates = [
        os.path.join(song_dir, base_name + ".lrc"),
        os.path.join(MUSIC_FOLDER, base_name + ".lrc"),
    ]

    for candidate in exact_candidates:
        if os.path.isfile(candidate):
            return candidate

    target_exact = (base_name + ".lrc").casefold()
    target_normalized = normalize_name(base_name)

    normalized_matches = []

    try:
        for root_dir, _, files in os.walk(MUSIC_FOLDER):
            for filename in files:
                if not filename.lower().endswith(".lrc"):
                    continue

                full_path = os.path.join(root_dir, filename)

                # Pontos nev eloszor.
                if filename.casefold() == target_exact:
                    return full_path

                # Utana rugalmas nev-azonositas.
                lrc_base = os.path.splitext(filename)[0]
                if normalize_name(lrc_base) == target_normalized:
                    normalized_matches.append(full_path)

        if normalized_matches:
            # Ha tobb is van, a dal mappajahoz legkozelebbit valasztjuk.
            normalized_matches.sort(
                key=lambda p: (
                    0 if os.path.dirname(p) == song_dir else 1,
                    len(p)
                )
            )
            return normalized_matches[0]

    except Exception as error:
        print("LRC KERESÉSI HIBA:", error)

    return None


def _lrclib_clean(value):
    value = str(value or "").strip()
    if value.casefold() in {
        "ismeretlen előadó",
        "ismeretlen eloado",
        "ismeretlen album",
        "unknown artist",
        "unknown album",
    }:
        return ""
    return value


def _lrclib_json(endpoint, params):
    query = urllib.parse.urlencode(
        {k: v for k, v in params.items() if v not in (None, "")}
    )
    url = "https://lrclib.net" + endpoint
    if query:
        url += "?" + query

    req = urllib.request.Request(
        url,
        headers={
            "User-Agent": "JustMusic/2.8 (local desktop music player; https://lrclib.net)"
        }
    )

    with urllib.request.urlopen(req, timeout=10) as response:
        return json.loads(response.read().decode("utf-8", errors="replace"))


def _save_auto_lrc(song_path, synced_lyrics):
    text = (synced_lyrics or "").strip()
    if not text:
        return None

    base_name = os.path.splitext(os.path.basename(song_path))[0]
    lrc_path = os.path.join(
        os.path.dirname(song_path),
        base_name + ".lrc"
    )

    with open(lrc_path, "w", encoding="utf-8-sig") as file:
        file.write(text)
        if not text.endswith("\n"):
            file.write("\n")

    return lrc_path


def _clean_track_title_for_search(title):
    """
    Eltavolitja a fajlnevbol/metaadatbol a tipikus YouTube-jellegu toldalekokat,
    hogy pl. 'Family Affair (Lyrics)' -> 'Family Affair' legyen.
    """
    title = str(title or "").strip()

    # Zarojelezett / szogletes toldalekok.
    patterns = [
        r"\s*[\(\[]\s*lyrics?\s*[\)\]]\s*$",
        r"\s*[\(\[]\s*official\s+lyrics?\s*[\)\]]\s*$",
        r"\s*[\(\[]\s*official\s+audio\s*[\)\]]\s*$",
        r"\s*[\(\[]\s*official\s+video\s*[\)\]]\s*$",
        r"\s*[\(\[]\s*audio\s*[\)\]]\s*$",
        r"\s*[\(\[]\s*video\s*[\)\]]\s*$",
        r"\s*[\(\[]\s*music\s+video\s*[\)\]]\s*$",
        r"\s*[\(\[]\s*hd\s*[\)\]]\s*$",
        r"\s*[\(\[]\s*4k\s*[\)\]]\s*$",
        r"\s*[\(\[]\s*explicit\s*[\)\]]\s*$",
        r"\s*[\(\[]\s*clean\s*[\)\]]\s*$",
    ]

    changed = True
    while changed:
        changed = False
        for pattern in patterns:
            new_title = re.sub(
                pattern,
                "",
                title,
                flags=re.IGNORECASE
            ).strip()

            if new_title != title:
                title = new_title
                changed = True

    # Kotojeles utotagok.
    title = re.sub(
        r"\s*[-–—]\s*(lyrics?|official\s+audio|official\s+video|audio|video|music\s+video)\s*$",
        "",
        title,
        flags=re.IGNORECASE
    ).strip()

    return title


def _normalize_search_text(text):
    text = str(text or "").strip().casefold()
    text = re.sub(r"\s+", " ", text)
    return text


def _filename_artist_title(track):
    """
    Fallback a fájlnévből, többféle kötőjellel.
    """
    path = str(track.get("path", ""))
    base = os.path.splitext(
        os.path.basename(path)
    )[0]

    artist, title = _parse_artist_title_from_filename(
        base
    )

    return artist, title


def _score_lrclib_result(item, title, artist, duration):
    score = 0

    result_title = _normalize_search_text(
        item.get("trackName") or item.get("name")
    )
    result_artist = _normalize_search_text(
        item.get("artistName")
    )

    wanted_title = _normalize_search_text(title)
    wanted_artist = _normalize_search_text(artist)

    if wanted_title and result_title == wanted_title:
        score += 120
    elif wanted_title and (
        wanted_title in result_title
        or result_title in wanted_title
    ):
        score += 70

    if wanted_artist and result_artist == wanted_artist:
        score += 120
    elif wanted_artist and (
        wanted_artist in result_artist
        or result_artist in wanted_artist
    ):
        score += 60

    result_duration = item.get("duration")

    if duration and result_duration:
        try:
            diff = abs(
                float(result_duration)
                - float(duration)
            )

            if diff <= 2:
                score += 80
            elif diff <= 5:
                score += 45
            elif diff <= 10:
                score += 20
            elif diff > 30:
                score -= 30
        except Exception:
            pass

    if item.get("syncedLyrics"):
        score += 50

    return score


def _search_lrclib(params):
    try:
        results = _lrclib_json(
            "/api/search",
            params
        )

        if isinstance(results, list):
            return results

    except urllib.error.HTTPError as error:
        print(
            "LRCLIB SEARCH HTTP HIBA:",
            error.code,
            params
        )

    except Exception as error:
        print(
            "LRCLIB SEARCH HIBA:",
            error,
            params
        )

    return []


def _find_lrclib_lyrics(track, duration):
    """
    LRCLIB fallback sorrend:

    1. syncedLyrics -> automatikus .lrc
    2. plainLyrics  -> betöltés az LRC készítőbe
    3. semmi        -> kézi LRC

    A keresés több, egyre lazább próbát tesz.
    """

    if track is None:
        return {
            "synced": None,
            "plain": None,
            "match": None,
        }

    title = _lrclib_clean(
        track.get("title")
    )

    # Utolsó takarítás LRCLIB keresés előtt.
    title = _clean_download_title(title)
    title = _clean_track_title_for_search(title)

    artist = _lrclib_clean(
        track.get("artist")
    )

    album = _lrclib_clean(
        track.get("album")
    )

    file_artist, file_title = _filename_artist_title(
        track
    )

    file_title = _clean_download_title(
        file_title
    )

    file_title = _clean_track_title_for_search(
        file_title
    )

    if not title:
        title = file_title

    if not artist:
        artist = file_artist

    all_results = []
    exact_plain = None
    exact_match = None

    # 1. Pontos /api/get
    if (
        title
        and artist
        and album
        and duration
        and duration > 0
    ):
        try:
            data = _lrclib_json(
                "/api/get",
                {
                    "track_name": title,
                    "artist_name": artist,
                    "album_name": album,
                    "duration": int(round(duration)),
                }
            )

            synced = data.get(
                "syncedLyrics"
            )

            plain = data.get(
                "plainLyrics"
            )

            if synced:
                print(
                    "LRCLIB: pontos synced találat",
                    artist,
                    "-",
                    title
                )

                return {
                    "synced": synced,
                    "plain": plain,
                    "match": data,
                }

            if plain:
                exact_plain = plain
                exact_match = data

        except urllib.error.HTTPError as error:
            if error.code != 404:
                print(
                    "LRCLIB GET HTTP HIBA:",
                    error.code
                )

        except Exception as error:
            print(
                "LRCLIB GET HIBA:",
                error
            )

    # 2. Cím + előadó
    if title:
        params = {
            "track_name": title
        }

        if artist:
            params["artist_name"] = artist

        all_results.extend(
            _search_lrclib(params)
        )

    # 3. Szabad keresés: előadó + cím
    query = " ".join(
        part
        for part in (artist, title)
        if part
    ).strip()

    if query:
        all_results.extend(
            _search_lrclib(
                {
                    "q": query
                }
            )
        )

    # 4. Csak cím
    if title:
        all_results.extend(
            _search_lrclib(
                {
                    "q": title
                }
            )
        )

    # 5. Fájlnév alapján is, ha eltér
    if file_title and (
        _normalize_search_text(file_title)
        != _normalize_search_text(title)
    ):
        params = {
            "track_name": file_title
        }

        if file_artist:
            params["artist_name"] = file_artist

        all_results.extend(
            _search_lrclib(params)
        )

    # Duplikációk eltávolítása
    unique = []
    seen_ids = set()

    for item in all_results:
        item_id = item.get("id")

        key = (
            item_id
            if item_id is not None
            else (
                item.get("trackName"),
                item.get("artistName"),
                item.get("duration")
            )
        )

        if key in seen_ids:
            continue

        seen_ids.add(key)
        unique.append(item)

    # =====================================================
    # ELSŐDLEGES: szinkronizált dalszöveg
    # =====================================================
    synced_candidates = [
        item
        for item in unique
        if item.get("syncedLyrics")
    ]

    if synced_candidates:
        synced_candidates.sort(
            key=lambda item: _score_lrclib_result(
                item,
                title,
                artist,
                duration
            ),
            reverse=True
        )

        best = synced_candidates[0]

        print(
            "LRCLIB SYNCED TALÁLAT:",
            best.get("artistName"),
            "-",
            best.get("trackName")
        )

        return {
            "synced": best.get("syncedLyrics"),
            "plain": best.get("plainLyrics"),
            "match": best,
        }

    # =====================================================
    # FALLBACK: sima, nem időzített dalszöveg
    # =====================================================
    plain_candidates = [
        item
        for item in unique
        if item.get("plainLyrics")
    ]

    if plain_candidates:
        plain_candidates.sort(
            key=lambda item: _score_lrclib_result(
                item,
                title,
                artist,
                duration
            ),
            reverse=True
        )

        best = plain_candidates[0]

        print(
            "LRCLIB PLAIN TALÁLAT:",
            best.get("artistName"),
            "-",
            best.get("trackName")
        )

        return {
            "synced": None,
            "plain": best.get("plainLyrics"),
            "match": best,
        }

    # Ha csak a pontos GET adott plain lyrics-et.
    if exact_plain:
        print(
            "LRCLIB PLAIN PONTOS TALÁLAT:",
            artist,
            "-",
            title
        )

        return {
            "synced": None,
            "plain": exact_plain,
            "match": exact_match,
        }

    print(
        "LRCLIB: sem synced, sem plain lyrics:",
        artist,
        "-",
        title
    )

    return {
        "synced": None,
        "plain": None,
        "match": None,
    }




def _lyricsovh_request_json(url):
    request = urllib.request.Request(
        url,
        headers={
            "User-Agent": "JustMusic/4.7 (local desktop music player)"
        }
    )

    with urllib.request.urlopen(
        request,
        timeout=15
    ) as response:
        raw = response.read().decode(
            "utf-8",
            errors="replace"
        )

    return json.loads(raw)


def _lyricsovh_direct(artist, title):
    artist = _clean_download_artist(
        str(artist or "").strip()
    )
    title = _clean_download_title(
        str(title or "").strip()
    )

    if not artist or not title:
        return None

    url = (
        "https://api.lyrics.ovh/v1/"
        + urllib.parse.quote(artist, safe="")
        + "/"
        + urllib.parse.quote(title, safe="")
    )

    try:
        data = _lyricsovh_request_json(url)

        lyrics_text = str(
            data.get("lyrics")
            or ""
        ).strip()

        return lyrics_text or None

    except urllib.error.HTTPError as error:
        if error.code != 404:
            print(
                "LYRICS.OVH HTTP HIBA:",
                error.code,
                artist,
                "-",
                title
            )

    except Exception as error:
        print(
            "LYRICS.OVH HIBA:",
            error
        )

    return None


def _lyricsovh_suggestions(query):
    query = str(query or "").strip()

    if not query:
        return []

    url = (
        "https://api.lyrics.ovh/suggest/"
        + urllib.parse.quote(
            query,
            safe=""
        )
    )

    try:
        data = _lyricsovh_request_json(
            url
        )

        items = data.get(
            "data",
            []
        )

        return items if isinstance(
            items,
            list
        ) else []

    except Exception as error:
        print(
            "LYRICS.OVH SUGGEST HIBA:",
            error
        )
        return []


def _lyricsovh_find_plain(track):
    """
    lyrics.ovh fallback:
    1. exact artist + title
    2. feat. nélküli főelőadó + title
    3. suggestion keresés, majd exact lekérés a találatból
    """

    if track is None:
        return None

    artist = _clean_download_artist(
        track.get("artist")
    )

    title = _clean_download_title(
        track.get("title")
    )

    title = _clean_track_title_for_search(
        title
    )

    # 1. Pontos lekérés
    direct = _lyricsovh_direct(
        artist,
        title
    )

    if direct:
        print(
            "LYRICS.OVH PONTOS TALÁLAT:",
            artist,
            "-",
            title
        )
        return direct

    # 2. Sok adatbázis a közreműködő nélkül tárolja a számot.
    main_artist = re.split(
        r"\s+(?:feat\.?|ft\.?|featuring)\s+",
        artist,
        maxsplit=1,
        flags=re.IGNORECASE
    )[0].strip()

    if (
        main_artist
        and main_artist.casefold()
        != artist.casefold()
    ):
        direct = _lyricsovh_direct(
            main_artist,
            title
        )

        if direct:
            print(
                "LYRICS.OVH FŐELŐADÓ TALÁLAT:",
                main_artist,
                "-",
                title
            )
            return direct

    # 3. Suggest endpoint - Deezer alapú névfelismerés.
    query = " ".join(
        part
        for part in (
            main_artist or artist,
            title
        )
        if part
    ).strip()

    suggestions = _lyricsovh_suggestions(
        query
    )

    wanted_title = _normalize_search_text(
        title
    )

    wanted_artist = _normalize_search_text(
        main_artist or artist
    )

    scored = []

    for item in suggestions[:15]:
        result_title = str(
            item.get("title")
            or ""
        ).strip()

        artist_obj = item.get(
            "artist"
        ) or {}

        result_artist = str(
            artist_obj.get("name")
            or ""
        ).strip()

        score = 0

        nt = _normalize_search_text(
            result_title
        )

        na = _normalize_search_text(
            result_artist
        )

        if wanted_title and nt == wanted_title:
            score += 120
        elif wanted_title and (
            wanted_title in nt
            or nt in wanted_title
        ):
            score += 65

        if wanted_artist and na == wanted_artist:
            score += 100
        elif wanted_artist and (
            wanted_artist in na
            or na in wanted_artist
        ):
            score += 50

        scored.append(
            (
                score,
                result_artist,
                result_title
            )
        )

    scored.sort(
        reverse=True,
        key=lambda item: item[0]
    )

    for score, result_artist, result_title in scored[:5]:
        # Ne próbáljunk teljesen irreleváns találatokat.
        if score < 60:
            continue

        plain = _lyricsovh_direct(
            result_artist,
            result_title
        )

        if plain:
            print(
                "LYRICS.OVH SUGGEST TALÁLAT:",
                result_artist,
                "-",
                result_title,
                "| score:",
                score
            )
            return plain

    return None



def auto_fetch_lyrics(song_path):
    track = current_track()

    if track is None:
        return

    key = str(song_path)

    if key in lyrics_fetching:
        return

    lyrics_fetching.add(key)
    duration = song_length

    def show_plain_fallback(
        source_name,
        plain_text
    ):
        plain_lyrics_cache[
            song_path
        ] = plain_text

        lyrics_fetching.discard(
            key
        )

        now = current_track()

        if not (
            now
            and now.get("path")
            == song_path
        ):
            return

        for widget in lyrics_frame.winfo_children():
            widget.destroy()

        tk.Label(
            lyrics_frame,
            text="Találtam dalszöveget ✅",
            font=("Arial", 13, "bold"),
            fg=JM_CYAN,
            bg=JM_BG,
            justify="center"
        ).pack(
            pady=(20, 4),
            padx=10
        )

        tk.Label(
            lyrics_frame,
            text=(
                f"Forrás: {source_name}\n"
                "Nincs kész szinkronizált LRC, "
                "de a sima dalszöveget betöltöttem."
            ),
            font=("Arial", 10),
            fg=JM_MUTED,
            bg=JM_BG,
            wraplength=330,
            justify="center"
        ).pack(
            pady=(0, 10),
            padx=10
        )

        tk.Button(
            lyrics_frame,
            text="⏱ IDŐZÍTÉS AZ LRC KÉSZÍTŐBEN",
            command=lambda:
                open_lrc_editor(
                    plain_lyrics_cache.get(
                        song_path,
                        ""
                    )
                ),
            bg=JM_CYAN,
            fg="black",
            activebackground=JM_CYAN_BRIGHT,
            activeforeground="black",
            borderwidth=0,
            relief="flat",
            font=("Arial", 9, "bold"),
            padx=10,
            pady=7
        ).pack(
            pady=(0, 14)
        )

        # Plain lyrics előnézet.
        for line in plain_text.splitlines():
            line = line.strip()

            if not line:
                continue

            tk.Label(
                lyrics_frame,
                text=line,
                font=("Arial", 11),
                fg=JM_TEXT_2,
                bg=JM_BG,
                justify="center",
                wraplength=330,
                anchor="center"
            ).pack(
                fill="x",
                pady=2,
                padx=8
            )

        root.after_idle(
            update_lyrics_canvas
        )

    def worker():
        try:
            # =============================================
            # 1. LRCLIB
            # =============================================
            result = _find_lrclib_lyrics(
                track,
                duration
            )

            synced = result.get(
                "synced"
            )

            plain = result.get(
                "plain"
            )

            if synced:
                saved = _save_auto_lrc(
                    song_path,
                    synced
                )

                def success_synced():
                    lyrics_fetching.discard(
                        key
                    )

                    now = current_track()

                    if (
                        now
                        and now.get("path")
                        == song_path
                    ):
                        load_lyrics(
                            song_path,
                            allow_online=False
                        )

                    print(
                        "AUTO LRC ELMENTVE:",
                        saved
                    )

                root.after(
                    0,
                    success_synced
                )
                return

            if plain:
                root.after(
                    0,
                    lambda text=plain:
                        show_plain_fallback(
                            "LRCLIB",
                            text
                        )
                )
                return

            # =============================================
            # 2. lyrics.ovh külső plain lyrics fallback
            # =============================================
            external_plain = _lyricsovh_find_plain(
                track
            )

            if external_plain:
                root.after(
                    0,
                    lambda text=external_plain:
                        show_plain_fallback(
                            "lyrics.ovh",
                            text
                        )
                )
                return

            # =============================================
            # 3. SEMMI
            # =============================================
            def not_found():
                lyrics_fetching.discard(
                    key
                )

                now = current_track()

                if not (
                    now
                    and now.get("path")
                    == song_path
                ):
                    return

                for widget in lyrics_frame.winfo_children():
                    widget.destroy()

                tk.Label(
                    lyrics_frame,
                    text="Nem találtam dalszöveget.",
                    font=("Arial", 13, "bold"),
                    fg=JM_MUTED,
                    bg=JM_BG,
                    wraplength=330,
                    justify="center"
                ).pack(
                    pady=(30, 8),
                    padx=10
                )

                tk.Label(
                    lyrics_frame,
                    text=(
                        "LRCLIB és lyrics.ovh is ellenőrizve.\n"
                        "Ehhez a dalhoz marad az LRC készítő."
                    ),
                    font=("Arial", 10),
                    fg="#555555",
                    bg=JM_BG,
                    wraplength=330,
                    justify="center"
                ).pack()

            root.after(
                0,
                not_found
            )

        except Exception as error:
            print(
                "AUTOMATIKUS LYRICS HIBA:",
                error
            )

            def failed():
                lyrics_fetching.discard(
                    key
                )

            root.after(
                0,
                failed
            )

    threading.Thread(
        target=worker,
        daemon=True
    ).start()



def load_lyrics(song_path, allow_online=True):
    global lyrics
    lyrics = []

    for widget in lyrics_frame.winfo_children():
        widget.destroy()

    lrc_path = find_lyrics_file(song_path)

    if not lrc_path:
        if allow_online:
            tk.Label(
                lyrics_frame,
                text="Automatikus dalszöveg-keresés...",
                font=("Arial", 14, "bold"),
                fg=JM_CYAN,
                bg=JM_BG
            ).pack(pady=(30, 6))

            tk.Label(
                lyrics_frame,
                text="LRCLIB + lyrics.ovh",
                font=("Arial", 9),
                fg="#555555",
                bg=JM_BG
            ).pack()

            auto_fetch_lyrics(song_path)
        else:
            tk.Label(
                lyrics_frame,
                text="Ehhez a számhoz nincs helyi dalszöveg.",
                font=("Arial", 14, "bold"),
                fg=JM_MUTED,
                bg=JM_BG
            ).pack(pady=(30, 6))
        return

    try:
        current_time = None
        current_block = []

        with open(lrc_path, "r", encoding="utf-8-sig", errors="replace") as file:
            for raw_line in file:
                line = raw_line.rstrip("\r\n")

                if not line.strip():
                    if current_time is not None and current_block:
                        text = "\n".join(current_block).strip()
                        if text:
                            lyrics.append((current_time, text))
                    current_time = None
                    current_block = []
                    continue

                match = re.match(
                    r"\[(\d+):(\d+(?:\.\d+)?)\](.*)",
                    line
                )

                if match:
                    if current_time is not None and current_block:
                        text = "\n".join(current_block).strip()
                        if text:
                            lyrics.append((current_time, text))

                    minutes = int(match.group(1))
                    seconds = float(match.group(2))
                    current_time = minutes * 60 + seconds
                    current_block = []

                    first_text = match.group(3).strip()
                    if first_text:
                        current_block.append(first_text)

                elif current_time is not None:
                    current_block.append(line.strip())

        if current_time is not None and current_block:
            text = "\n".join(current_block).strip()
            if text:
                lyrics.append((current_time, text))

        lyrics.sort(key=lambda x: x[0])

        if not lyrics:
            tk.Label(
                lyrics_frame,
                text="Az LRC fájlban nincs időzített dalszöveg.",
                font=("Arial", 14),
                fg=JM_MUTED,
                bg=JM_BG
            ).pack(pady=30)
            return

        # Üres tér felül/alul: így a legelső és legutolsó sor is
        # középre tud kerülni, nem tapad a panel széléhez.
        top_lyrics_spacer = tk.Frame(
            lyrics_frame,
            bg=JM_BG,
            height=120
        )
        top_lyrics_spacer.pack(
            fill="x"
        )

        for start_time, text in lyrics:
            lyric_label = tk.Label(
                lyrics_frame,
                text=text,
                font=("Arial", 12),
                fg=JM_MUTED,
                bg=JM_BG,
                justify="center",
                wraplength=335,
                anchor="center",
                cursor="hand2"
            )

            lyric_label.pack(
                fill="x",
                pady=3,
                padx=8
            )

            # Kattintás = ugrás az adott LRC sor időpontjára.
            lyric_label.bind(
                "<Button-1>",
                lambda event, ts=start_time:
                    seek_to_lyric_time(ts)
            )

        bottom_lyrics_spacer = tk.Frame(
            lyrics_frame,
            bg=JM_BG,
            height=180
        )
        bottom_lyrics_spacer.pack(
            fill="x"
        )

        root.after_idle(update_lyrics_canvas)

    except Exception as error:
        tk.Label(
            lyrics_frame,
            text="LRC hiba:\n" + str(error),
            font=("Arial", 13),
            fg="#ff5555",
            bg=JM_BG
        ).pack(pady=20)

def _start_track_playback(
    track,
    playback_path,
    request_id,
    start_position=0.0,
    start_paused=False
):
    global paused
    global song_started
    global song_length
    global current_lyric_index
    global play_start_time
    global paused_at
    global paused_total
    global next_play_fade_ms
    global current_playback_path

    if request_id != eq_play_request_id:
        return

    now_track = current_track()

    if (
        now_track is None
        or now_track.get("path")
        != track.get("path")
    ):
        return

    try:
        pygame.mixer.music.stop()
        pygame.mixer.music.load(
            playback_path
        )

        current_playback_path = playback_path

        song_length = get_song_length(
            track["path"]
        )

        start_position = max(
            0.0,
            min(
                float(start_position or 0.0),
                max(
                    song_length - 0.05,
                    0.0
                )
            )
        )

        fade_ms = int(
            max(
                0,
                next_play_fade_ms
            )
        )

        next_play_fade_ms = 0

        try:
            pygame.mixer.music.play(
                loops=0,
                start=start_position,
                fade_ms=fade_ms
            )
        except Exception:
            # Bizonyos codec/build kombináció nem szereti a start paramétert.
            pygame.mixer.music.play(
                fade_ms=fade_ms
            )

            start_position = 0.0

        now = time.perf_counter()

        play_start_time = (
            now
            - start_position
        )

        paused_at = 0.0
        paused_total = 0.0

        display_title = _clean_track_title_for_search(
            track["title"]
        )

        current_label.config(
            text=f'{track["artist"]} — {display_title}'
        )

        try:
            now_playing_small.config(
                text=display_title
            )

            if queued_current is not None:
                now_playing_hint.config(
                    text=f'{track["artist"]} • lejátszási sorból'
                )
            elif (
                playback_path != track["path"]
                and (
                    (
                        eq_enabled
                        and not _eq_is_flat()
                    )
                    or normalization_enabled
                )
            ):
                effects = []

                if (
                    eq_enabled
                    and not _eq_is_flat()
                ):
                    effects.append(
                        "EQ"
                    )

                if normalization_enabled:
                    effects.append(
                        "RG"
                    )

                now_playing_hint.config(
                    text=(
                        f'{track["artist"]} • '
                        + " + ".join(
                            effects
                        )
                    )
                )
            else:
                now_playing_hint.config(
                    text=track["artist"]
                )

        except Exception:
            pass

        refresh_now_playing_visuals(
            track
        )

        if track["album"].casefold() in {
            "ismeretlen album",
            "unknown album"
        }:
            album_label.config(
                text=""
            )
        else:
            album_label.config(
                text=track["album"]
            )

        progress.config(
            to=max(
                song_length,
                1
            )
        )

        progress.set(
            start_position
        )

        current_time_label.config(
            text=format_time(
                start_position
            )
        )

        total_time_label.config(
            text=format_time(
                song_length
            )
        )

        current_lyric_index = -1

        load_lyrics(
            track["path"]
        )

        paused = False
        song_started = True

        register_track_start(
            track,
            start_position
        )

        if start_paused:
            pygame.mixer.music.pause()
            paused = True
            paused_at = now
            play_button.config(
                text="▶"
            )
        else:
            play_button.config(
                text="⏸"
            )

        if start_position > 0:
            update_lyrics(
                start_position
            )

    except Exception as error:
        song_started = False

        current_label.config(
            text="Lejátszási hiba: "
            + str(error)
        )

        print(
            "HIBA:",
            error
        )


def play_song(
    start_position=0.0,
    start_paused=False
):
    global eq_play_request_id

    track = current_track()

    if track is None:
        return

    eq_play_request_id += 1
    request_id = eq_play_request_id

    processing_needed = (
        (
            eq_enabled
            and not _eq_is_flat()
        )
        or normalization_enabled
    )

    if processing_needed:
        if not _ffmpeg_path():
            _set_eq_status(
                "FFmpeg nincs — eredeti hang indul.",
                "#ff7777"
            )

            _start_track_playback(
                track,
                track["path"],
                request_id,
                start_position,
                start_paused
            )
            return

        _prepare_eq_async(
            track,
            request_id,
            start_position,
            start_paused
        )

        return

    _start_track_playback(
        track,
        track["path"],
        request_id,
        start_position,
        start_paused
    )



def toggle_pause():
    global paused, paused_at, paused_total
    if not song_started:
        play_song()
        return
    if paused:
        now = time.perf_counter()
        if paused_at > 0:
            paused_total += now - paused_at
        pygame.mixer.music.unpause()
        paused = False
        play_button.config(text=JM_ICONS["pause"])
    else:
        paused_at = time.perf_counter()
        pygame.mixer.music.pause()
        paused = True
        play_button.config(text=JM_ICONS["play"])


def next_song(auto=False, allow_crossfade=True):
    global queued_current

    should_mix = (
        mix_auto_transition_enabled
        if auto
        else mix_manual_transition_enabled
    )

    if (
        allow_crossfade
        and should_mix
        and (
            crossfade_enabled
            or mix_gapless_enabled
        )
        and song_started
        and not paused
        and not transition_in_progress
    ):
        start_next_transition(
            auto=auto
        )
        return

    # Repeat one csak automatikus dalvégnél ismétel.
    if auto and repeat_mode == "one":
        play_song()
        return

    # A kézzel összeállított queue elsőbbséget élvez.
    if play_queue:
        queued_current = play_queue.pop(0)
        update_queue_button()
        refresh_queue_window()
        play_song()
        return

    # Queue-dal után vissza az eredeti listába.
    if queued_current is not None:
        queued_current = None

        if _advance_library_forward():
            play_song()
        elif auto:
            stop_playback_at_end()

        return

    if _advance_library_forward():
        play_song()
    elif auto:
        stop_playback_at_end()



def previous_song():
    global queued_current

    cancel_pending_transition()

    # Queue-dalból vissza az eredeti aktuális dalra.
    if queued_current is not None:
        queued_current = None
        play_song()
        return

    if _advance_library_backward():
        play_song()



def get_current_position():
    if not song_started:
        return 0.0
    if paused:
        return max(0.0, paused_at - play_start_time - paused_total)
    return max(0.0, time.perf_counter() - play_start_time - paused_total)


def keep_current_lyric_visible(index=None, force=False):
    """
    Nem rángatja minden sornál a dalszöveget.
    Csak akkor görget, ha az aktuális (fehér) sor már
    kicsúszna a látható területből.

    force=True esetén (pl. beletekerés után) biztosan
    a panel közepe környékére teszi az aktuális sort.
    """

    if not lyrics:
        return

    blocks = [
        widget
        for widget in lyrics_frame.winfo_children()
        if isinstance(widget, tk.Label)
    ]

    if index is None:
        index = current_lyric_index

    if not (0 <= index < len(blocks)):
        return

    root.update_idletasks()
    update_lyrics_canvas()

    current_widget = blocks[index]

    try:
        content_height = max(
            float(lyrics_frame.winfo_reqheight()),
            float(lyrics_frame.winfo_height()),
            1.0
        )

        viewport_height = max(
            float(canvas.winfo_height()),
            1.0
        )

        # A jelenleg látható rész valódi koordinátái.
        visible_top = float(
            canvas.canvasy(0)
        )

        visible_bottom = (
            visible_top
            + viewport_height
        )

        widget_top = float(
            current_widget.winfo_y()
        )

        widget_bottom = (
            widget_top
            + float(
                current_widget.winfo_height()
            )
        )

        # Biztonsági zóna: ne érjen hozzá a fehér sor
        # se a panel tetejéhez, se az aljához.
        safe_top = (
            visible_top
            + viewport_height * 0.18
        )

        safe_bottom = (
            visible_bottom
            - viewport_height * 0.18
        )

        needs_scroll = (
            force
            or widget_top < safe_top
            or widget_bottom > safe_bottom
        )

        if not needs_scroll:
            return

        widget_center = (
            widget_top
            + widget_bottom
        ) / 2.0

        # Kb. a látható panel 42%-ára tesszük:
        # nem teljesen középre, így több következő sort látni.
        wanted_top = (
            widget_center
            - viewport_height * 0.42
        )

        max_top = max(
            content_height
            - viewport_height,
            0.0
        )

        wanted_top = max(
            0.0,
            min(
                wanted_top,
                max_top
            )
        )

        fraction = (
            wanted_top / content_height
            if content_height > 0
            else 0.0
        )

        canvas.yview_moveto(
            max(
                0.0,
                min(
                    1.0,
                    fraction
                )
            )
        )

    except Exception as error:
        print(
            "LYRICS LÁTHATÓSÁGI HIBA:",
            error
        )




# =========================================================
# KATTINTHATO DALSZOVEG -> TEKERES AZ ADOTT SORHOZ
# =========================================================

def seek_to_lyric_time(lyric_timestamp):
    """
    Egy LRC sor időbélyegére ugrik.
    Működik előre- és visszatekerésre is,
    és megőrzi a pause állapotot.
    """
    global play_start_time
    global paused_at
    global paused_total
    global current_lyric_index
    global full_lyrics_active_index
    global seeking

    if not song_started:
        return

    cancel_pending_transition()

    try:
        # Az update_lyrics() a LYRICS_OFFSET-et hozzáadja
        # a lejátszási időhöz, ezért kattintásnál ezt visszavonjuk,
        # hogy pontosan a kiválasztott sor legyen aktív.
        target = float(
            lyric_timestamp
        ) - float(
            LYRICS_OFFSET
        )

        target = max(
            0.0,
            min(
                target,
                max(
                    song_length - 0.01,
                    0.0
                )
            )
        )

        seeking = True

        pygame.mixer.music.play(
            loops=0,
            start=target
        )

        now = time.perf_counter()

        play_start_time = (
            now - target
        )

        paused_total = 0.0

        if paused:
            pygame.mixer.music.pause()
            paused_at = now
        else:
            paused_at = 0.0

        progress.set(
            target
        )

        current_time_label.config(
            text=format_time(
                target
            )
        )

        # Kényszerítsük ki mindkét lyrics nézet frissítését.
        current_lyric_index = -1
        full_lyrics_active_index = -1

        update_lyrics(
            target
        )

        update_fullscreen_lyrics(
            target
        )

        # A kiválasztott sor kerüljön vissza jól látható helyre.
        root.after(
            20,
            lambda:
                keep_current_lyric_visible(
                    force=True
                )
        )

        root.after(
            50,
            lambda:
                _center_full_lyrics_line(
                    full_lyrics_active_index
                )
        )

    except Exception as error:
        print(
            "DALSZOVEG KATTINTAS / TEKERES HIBA:",
            error
        )

    finally:
        seeking = False



def update_lyrics(current_seconds):
    global current_lyric_index

    if not lyrics:
        return

    current_seconds += LYRICS_OFFSET
    new_index = -1

    for i, (start_time, _) in enumerate(lyrics):
        if current_seconds >= start_time:
            new_index = i
        else:
            break

    blocks = [
        widget
        for widget in lyrics_frame.winfo_children()
        if isinstance(widget, tk.Label)
    ]

    if new_index == current_lyric_index:
        return

    current_lyric_index = new_index

    for widget in blocks:
        widget.config(
            fg=JM_MUTED,
            font=("Arial", 12, "normal")
        )

    if 0 <= new_index < len(blocks):
        blocks[new_index].config(
            fg=JM_TEXT,
            font=("Arial", 14, "bold")
        )

        # Először hagyjuk a Tkintert újraméretezni,
        # utána görgetjük középre az aktív sort.
        # Csak akkor mozgatjuk a lyrics panelt,
        # ha a fehér sor már kicsúszna a képből.
        root.after_idle(
            lambda i=new_index:
                keep_current_lyric_visible(
                    i,
                    force=False
                )
        )

        root.after(
            80,
            lambda i=new_index:
                keep_current_lyric_visible(
                    i,
                    force=False
                )
        )


def start_seek(event=None):
    global seeking

    cancel_pending_transition()

    if song_started:
        seeking = True


def finish_seek(event=None):
    global seeking, play_start_time, paused_at, paused_total, current_lyric_index
    if not song_started:
        seeking = False
        return
    target = max(0.0, min(float(progress.get()), song_length))
    try:
        pygame.mixer.music.play(loops=0, start=target)
        now = time.perf_counter()
        play_start_time = now - target
        paused_total = 0.0
        if paused:
            pygame.mixer.music.pause()
            paused_at = now
        else:
            paused_at = 0.0
        current_lyric_index = -1
        update_lyrics(target)
        current_time_label.config(text=format_time(target))

        # Tekerés után a Tkinter több körben is átrendezheti a lyrics panelt.
        # Ezért biztosan visszaközpontosítjuk a fehér sort.
        root.after(
            30,
            lambda:
                keep_current_lyric_visible(
                    force=True
                )
        )
        root.after(
            150,
            lambda:
                keep_current_lyric_visible(
                    force=True
                )
        )
    except Exception as error:
        print("TEKERESI HIBA:", error)
    seeking = False


def update_progress():
    if song_started:
        current_seconds = get_current_position()

        if not seeking:
            progress.set(
                min(
                    current_seconds,
                    max(
                        song_length,
                        1
                    )
                )
            )

        current_time_label.config(
            text=format_time(
                current_seconds
            )
        )

        if not paused:
            update_lyrics(
                current_seconds
            )

        update_now_playing_progress(
            current_seconds
        )

        update_fullscreen_lyrics(
            current_seconds
        )

        refresh_mini_player(
            current_seconds
        )

        update_visualizers(
            current_seconds
        )

        refresh_connect_now_playing()

        tick_listening_stats()

    else:
        refresh_mini_player(
            0.0
        )

        update_visualizers(
            0.0
        )

        tick_listening_stats()

    try:
        refresh_nav_active()
    except Exception:
        pass

    root.after(
        100,
        update_progress
    )


def check_song_end():
    if (
        song_started
        and not paused
        and not transition_in_progress
    ):
        current_seconds = get_current_position()

        if song_length > 0:
            remaining = (
                song_length
                - current_seconds
            )

            # Sleep Timer "dal végén": ilyenkor nem engedjük,
            # hogy a crossfade előbb átváltson a következő számra.
            if sleep_timer_mode == "track_end":
                if (
                    remaining <= 0.20
                    or (
                        not pygame.mixer.music.get_busy()
                        and current_seconds >= song_length - 0.5
                    )
                ):
                    stop_for_sleep_timer()
                    return

            elif (
                mix_auto_transition_enabled
                and crossfade_enabled
                and mix_fade_out_seconds > 0
            ):
                out_ms, _ = _transition_fade_parts()

                fade_start = max(
                    out_ms / 1000.0,
                    0.15
                )

                if (
                    remaining <= fade_start
                    and remaining >= -0.5
                ):
                    next_song(
                        auto=True
                    )

            elif (
                mix_auto_transition_enabled
                and mix_gapless_enabled
                and remaining <= 0.08
            ):
                next_song(
                    auto=True
                )

            elif not pygame.mixer.music.get_busy():
                if current_seconds >= song_length - 0.5:
                    next_song(
                        auto=True
                    )

    root.after(
        100,
        check_song_end
    )





