# =========================================================
# BEEPITETT ZENEKERESO - JAMENDO
# =========================================================

def _jamendo_api_tracks(query, limit=20):
    params = {
        "client_id": JAMENDO_CLIENT_ID,
        "format": "json",
        "limit": limit,
        "search": query,
        "type": "single albumtrack",
        "audioformat": "mp32",
        "audiodlformat": "mp32",
        "imagesize": 200,
        "include": "musicinfo",
        "order": "relevance",
    }

    url = (
        "https://api.jamendo.com/v3.0/tracks/?"
        + urllib.parse.urlencode(params)
    )

    request = urllib.request.Request(
        url,
        headers={
            "User-Agent": "JustMusic/3.5 (local desktop music player)"
        }
    )

    with urllib.request.urlopen(
        request,
        timeout=15
    ) as response:
        data = json.loads(
            response.read().decode(
                "utf-8",
                errors="replace"
            )
        )

    headers = data.get("headers", {})

    if headers.get("status") != "success":
        raise RuntimeError(
            headers.get(
                "error_message",
                "Ismeretlen Jamendo API hiba."
            )
        )

    return data.get("results", [])


def _download_jamendo_track(track, parent_window=None):
    download_url = str(
        track.get("audiodownload")
        or ""
    ).strip()

    allowed = track.get(
        "audiodownload_allowed"
    )

    if not download_url or allowed is False:
        messagebox.showinfo(
            "JustMusic!",
            (
                "Ennek a dalnak az előadója nem engedélyezte "
                "a letöltést a Jamendón."
            ),
            parent=parent_window or root
        )
        return

    artist = str(
        track.get("artist_name")
        or "Ismeretlen előadó"
    ).strip()

    title = str(
        track.get("name")
        or "Ismeretlen dal"
    ).strip()

    filename = _safe_filename(
        f"{artist} - {title}.mp3"
    )

    final_path = _unique_download_path(
        filename
    )

    progress_window = tk.Toplevel(
        parent_window or root
    )
    progress_window.title(
        "JustMusic! - Letöltés"
    )
    progress_window.geometry(
        "440x165"
    )
    progress_window.resizable(
        False,
        False
    )
    progress_window.configure(
        bg=JM_PANEL
    )

    tk.Label(
        progress_window,
        text="Letöltés a Jamendóról",
        font=("Arial", 15, "bold"),
        fg=JM_TEXT,
        bg=JM_PANEL
    ).pack(
        pady=(20, 5)
    )

    tk.Label(
        progress_window,
        text=f"{artist} — {title}",
        font=("Arial", 10, "bold"),
        fg=JM_TEXT_2,
        bg=JM_PANEL,
        wraplength=390
    ).pack(
        padx=15,
        pady=(0, 8)
    )

    status_label = tk.Label(
        progress_window,
        text="Kapcsolódás...",
        font=("Arial", 10),
        fg=JM_CYAN,
        bg=JM_PANEL
    )
    status_label.pack(
        pady=5
    )

    def set_status(text):
        try:
            if progress_window.winfo_exists():
                status_label.config(
                    text=text
                )
        except Exception:
            pass

    def finish_success():
        try:
            if progress_window.winfo_exists():
                progress_window.destroy()
        except Exception:
            pass

        scan_library()
        show_all_tracks()

        messagebox.showinfo(
            "JustMusic! - Sikeres letöltés",
            (
                "✅ SIKERES LETÖLTÉS!\n\n"
                f"{artist} — {title}\n\n"
                "A dal bekerült a JustMusic! könyvtárába."
            ),
            parent=parent_window or root
        )

    def finish_error(message):
        try:
            if progress_window.winfo_exists():
                progress_window.destroy()
        except Exception:
            pass

        messagebox.showerror(
            "JustMusic! - Sikertelen letöltés",
            (
                "❌ SIKERTELEN LETÖLTÉS!\n\n"
                + str(message)
            ),
            parent=parent_window or root
        )

    def worker():
        temp_path = final_path + ".part"

        try:
            request = urllib.request.Request(
                download_url,
                headers={
                    "User-Agent": "JustMusic/3.5 (local desktop music player)"
                }
            )

            with urllib.request.urlopen(
                request,
                timeout=30
            ) as response:
                total_header = response.headers.get(
                    "Content-Length"
                )

                try:
                    total_size = int(
                        total_header
                    ) if total_header else 0
                except Exception:
                    total_size = 0

                downloaded = 0

                with open(
                    temp_path,
                    "wb"
                ) as file:
                    while True:
                        chunk = response.read(
                            1024 * 128
                        )

                        if not chunk:
                            break

                        file.write(
                            chunk
                        )

                        downloaded += len(
                            chunk
                        )

                        if total_size > 0:
                            percent = int(
                                downloaded * 100 / total_size
                            )
                            text = f"{percent}%"
                        else:
                            text = (
                                f"{downloaded / 1024 / 1024:.1f} MB"
                            )

                        root.after(
                            0,
                            lambda t=text:
                                set_status(t)
                        )

            os.replace(
                temp_path,
                final_path
            )

            root.after(
                0,
                finish_success
            )

        except Exception as error:
            try:
                if os.path.exists(temp_path):
                    os.remove(temp_path)
            except Exception:
                pass

            root.after(
                0,
                lambda e=error:
                    finish_error(str(e))
            )

    threading.Thread(
        target=worker,
        daemon=True
    ).start()



# =========================================================
# INTERNET ARCHIVE - KERESES + NYILVANOS AUDIO FAJLOK
# =========================================================

def _archive_json(url):
    request = urllib.request.Request(
        url,
        headers={
            "User-Agent": "JustMusic/3.8 (local desktop music player)"
        }
    )

    with urllib.request.urlopen(
        request,
        timeout=20
    ) as response:
        return json.loads(
            response.read().decode(
                "utf-8",
                errors="replace"
            )
        )


def _archive_search(query, rows=20):
    query = str(query or "").strip()

    if not query:
        return []

    # Csak audio itemek. A keresett szoveget cimben/creatorban
    # preferaljuk, de a teljes metaadatban is keressuk.
    search_expression = (
        'mediatype:audio AND '
        f'("{query}" OR title:("{query}") OR creator:("{query}"))'
    )

    params = [
        ("q", search_expression),
        ("fl[]", "identifier"),
        ("fl[]", "title"),
        ("fl[]", "creator"),
        ("fl[]", "description"),
        ("fl[]", "date"),
        ("fl[]", "licenseurl"),
        ("rows", str(rows)),
        ("page", "1"),
        ("output", "json"),
        ("sort[]", "downloads desc"),
    ]

    url = (
        "https://archive.org/advancedsearch.php?"
        + urllib.parse.urlencode(params)
    )

    data = _archive_json(url)

    return (
        data.get("response", {})
        .get("docs", [])
    )


def _archive_item_metadata(identifier):
    identifier = str(identifier or "").strip()

    if not identifier:
        return {}

    url = (
        "https://archive.org/metadata/"
        + urllib.parse.quote(
            identifier,
            safe=""
        )
    )

    return _archive_json(url)


def _archive_audio_files(identifier):
    data = _archive_item_metadata(
        identifier
    )

    files = data.get(
        "files",
        []
    )

    # Internet Archive storage servers.
    servers = []

    for key in ("d1", "d2"):
        server = str(
            data.get(key)
            or ""
        ).strip()

        if server and server not in servers:
            servers.append(server)

    audio_files = []

    for item in files:
        name = str(
            item.get("name")
            or ""
        )

        if not name:
            continue

        # Ne jelenjen meg privát / korlátozott fájl letöltésként.
        private_value = str(
            item.get("private")
            or ""
        ).strip().lower()

        if private_value in (
            "true",
            "1",
            "yes"
        ):
            continue

        ext = os.path.splitext(
            name
        )[1].lower()

        if ext not in SUPPORTED_AUDIO:
            continue

        source = str(
            item.get("source")
            or ""
        ).lower()

        format_name = str(
            item.get("format")
            or ext.lstrip(".").upper()
        )

        try:
            size = int(
                item.get("size")
                or 0
            )
        except Exception:
            size = 0

        audio_files.append(
            {
                "name": name,
                "format": format_name,
                "source": source,
                "size": size,
                "servers": list(servers),
            }
        )

    extension_priority = {
        ".mp3": 0,
        ".m4a": 1,
        ".ogg": 2,
        ".flac": 3,
        ".wav": 4,
    }

    def sort_key(item):
        ext = os.path.splitext(
            item["name"]
        )[1].lower()

        source_rank = (
            0
            if item["source"] == "original"
            else 1
        )

        return (
            source_rank,
            extension_priority.get(
                ext,
                99
            ),
            item["name"].casefold()
        )

    audio_files.sort(
        key=sort_key
    )

    return audio_files


def _archive_file_url(identifier, filename):
    encoded_identifier = urllib.parse.quote(
        str(identifier),
        safe=""
    )

    encoded_filename = urllib.parse.quote(
        str(filename),
        safe="/"
    )

    return (
        "https://archive.org/download/"
        + encoded_identifier
        + "/"
        + encoded_filename
    )


def _archive_download_urls(identifier, filename, servers=None):
    """
    Több URL-t próbálunk:
    1. archive.org/download
    2. az item d1/d2 storage szerverei
    """

    encoded_identifier = urllib.parse.quote(
        str(identifier),
        safe=""
    )

    encoded_filename = urllib.parse.quote(
        str(filename),
        safe="/"
    )

    urls = [
        (
            "https://archive.org/download/"
            + encoded_identifier
            + "/"
            + encoded_filename
        )
    ]

    for server in servers or []:
        server = str(server or "").strip()

        if not server:
            continue

        url = (
            "https://"
            + server
            + "/"
            + encoded_identifier
            + "/"
            + encoded_filename
        )

        if url not in urls:
            urls.append(url)

    return urls


def _download_archive_audio(identifier, file_info, parent_window=None, external_status=None):
    original_name = str(
        file_info.get("name")
        or ""
    )

