def add_local_music():
    files = filedialog.askopenfilenames(
        title="JustMusic! - Helyi zene hozzáadása",
        filetypes=[
            ("Támogatott zenék", "*.mp3 *.wav *.ogg *.flac *.m4a"),
            ("MP3", "*.mp3"),
            ("WAV", "*.wav"),
            ("OGG", "*.ogg"),
            ("FLAC", "*.flac"),
            ("M4A", "*.m4a"),
            ("Minden fájl", "*.*"),
        ]
    )

    if not files:
        return

    os.makedirs(MUSIC_FOLDER, exist_ok=True)

    added = []
    failed = []

    for source_path in files:
        try:
            source_path = str(source_path)
            ext = os.path.splitext(source_path)[1].lower()

            if ext not in SUPPORTED_AUDIO:
                failed.append(
                    (os.path.basename(source_path), "Nem támogatott formátum.")
                )
                continue

            original_name = os.path.basename(source_path)

            clean_name = _clean_downloaded_filename(
                original_name
            )

            destination = _unique_download_path(
                clean_name
            )

            shutil.copy2(
                source_path,
                destination
            )

            added.append(destination)

        except Exception as error:
            failed.append(
                (os.path.basename(str(source_path)), str(error))
            )

    scan_library()
    show_all_tracks()

    if added:
        message = (
            f"✅ {len(added)} zene hozzáadva!\n\n"
            "A fájlok bekerültek ide:\n"
            f"{MUSIC_FOLDER}"
        )

        if failed:
            message += f"\n\n⚠ {len(failed)} fájl nem sikerült."

        messagebox.showinfo(
            "JustMusic! - Helyi zene hozzáadása",
            message,
            parent=root
        )

    elif failed:
        details = "\n".join(
            f"• {name}: {reason}"
            for name, reason in failed[:8]
        )

        messagebox.showerror(
            "JustMusic! - Hiba",
            "❌ Egyetlen fájlt sem sikerült hozzáadni.\n\n" + details,
            parent=root
        )



def download_music_from_url():
    url = simpledialog.askstring(
        "JustMusic! - Zene letöltése",
        (
            "Illeszd be a KÖZVETLEN zenei fájl URL-jét.\n\n"
            "Támogatott: MP3, WAV, OGG, FLAC, M4A\n"
            "Példa: https://pelda.hu/zene.mp3"
        ),
        parent=root
    )

    if not url:
        return

    url = url.strip()

    parsed = urllib.parse.urlparse(
        url
    )

    if parsed.scheme not in (
        "http",
        "https"
    ):
        messagebox.showerror(
            "JustMusic!",
            "Csak http:// vagy https:// URL használható."
        )
        return

    progress_window = tk.Toplevel(
        root
    )

    progress_window.title(
        "JustMusic! - Letöltés"
    )

    progress_window.geometry(
        "430x150"
    )

    progress_window.resizable(
        False,
        False
    )

    progress_window.configure(
        bg=JM_PANEL
    )

    tk.Label(
        progress_window,
        text="Zene letöltése...",
        font=("Arial", 15, "bold"),
        fg=JM_TEXT,
        bg=JM_PANEL
    ).pack(
        pady=(20, 7)
    )

    status_label = tk.Label(
        progress_window,
        text="Kapcsolódás...",
        font=("Arial", 10),
        fg=JM_TEXT_2,
        bg=JM_PANEL,
        wraplength=390
    )

    status_label.pack(
        padx=15,
        pady=5
    )

    def set_status(text):
        try:
            if progress_window.winfo_exists():
                status_label.config(
                    text=text
                )
        except Exception:
            pass

    def finish_success(path):
        try:
            if progress_window.winfo_exists():
                progress_window.destroy()
        except Exception:
            pass

        # Ujraolvassuk a zenetarat.
        scan_library()

        messagebox.showinfo(
            "JustMusic!",
            (
                "Letöltés kész! 🎵\n\n"
                f"{os.path.basename(path)}\n\n"
                "A zene bekerült a JustMusic! könyvtárába."
            )
        )

        show_all_tracks()

    def finish_error(message):
        try:
            if progress_window.winfo_exists():
                progress_window.destroy()
        except Exception:
            pass

        messagebox.showerror(
            "JustMusic! - Letöltési hiba",
            message
        )

    def worker():
        temp_path = None

        try:
            request = urllib.request.Request(
                url,
                headers={
                    "User-Agent": (
                        "JustMusic/3.4 "
                        "(local desktop music player)"
                    )
                }
            )

            with urllib.request.urlopen(
                request,
                timeout=25
            ) as response:

                content_type = response.headers.get(
                    "Content-Type",
                    ""
                )

                filename = _filename_from_response(
                    url,
                    response
                )

                # Ha a szerver audio MIME-ot ad, de nincs jo kiterjesztes,
                # probalunk ertelmeset adni neki.
                ext = os.path.splitext(
                    filename
                )[1].lower()

                if ext not in SUPPORTED_AUDIO:
                    mime = content_type.split(
                        ";",
                        1
                    )[0].strip().lower()

                    mime_extensions = {
                        "audio/mpeg": ".mp3",
                        "audio/mp3": ".mp3",
                        "audio/wav": ".wav",
                        "audio/x-wav": ".wav",
                        "audio/ogg": ".ogg",
                        "audio/flac": ".flac",
                        "audio/x-flac": ".flac",
                        "audio/mp4": ".m4a",
                        "audio/x-m4a": ".m4a",
                    }

                    if mime in mime_extensions:
                        filename = (
                            os.path.splitext(
                                filename
                            )[0]
                            + mime_extensions[mime]
                        )

                if not _looks_like_audio(
                    filename,
                    content_type
                ):
                    raise ValueError(
                        (
                            "A megadott URL nem közvetlen zenei fájlra mutat.\n\n"
                            f"Kapott tartalomtípus: {content_type or 'ismeretlen'}"
                        )
                    )

                final_path = _unique_download_path(
                    filename
                )

                temp_path = (
                    final_path
                    + ".part"
                )

                total_header = response.headers.get(
                    "Content-Length"
                )

                try:
                    total_size = int(
                        total_header
                    ) if total_header else 0
                except Exception:
                    total_size = 0

                downloaded = 0

                with open(
                    temp_path,
                    "wb"
                ) as file:
                    while True:
                        chunk = response.read(
                            1024 * 128
                        )

                        if not chunk:
                            break

                        file.write(
                            chunk
                        )

                        downloaded += len(
                            chunk
                        )

                        if total_size > 0:
                            percent = int(
                                downloaded
                                * 100
                                / total_size
                            )

                            mb_done = (
                                downloaded
                                / 1024
                                / 1024
                            )

                            mb_total = (
                                total_size
                                / 1024
                                / 1024
                            )

                            text = (
                                f"{percent}%  •  "
                                f"{mb_done:.1f} / {mb_total:.1f} MB"
                            )
                        else:
                            mb_done = (
                                downloaded
                                / 1024
                                / 1024
                            )

                            text = (
                                f"{mb_done:.1f} MB letöltve..."
                            )

                        root.after(
                            0,
                            lambda t=text:
                                set_status(t)
                        )

                os.replace(
                    temp_path,
                    final_path
                )

                root.after(
                    0,
                    lambda p=final_path:
                        finish_success(p)
                )

        except urllib.error.HTTPError as error:
            if temp_path and os.path.exists(temp_path):
                try:
                    os.remove(
                        temp_path
                    )
                except Exception:
                    pass

            root.after(
                0,
                lambda e=error:
                    finish_error(
                        f"HTTP hiba: {e.code} {e.reason}"
                    )
            )

        except urllib.error.URLError as error:
            if temp_path and os.path.exists(temp_path):
                try:
                    os.remove(
                        temp_path
                    )
                except Exception:
                    pass

            root.after(
                0,
                lambda e=error:
                    finish_error(
                        f"Kapcsolati hiba:\n{e.reason}"
                    )
            )

        except Exception as error:
            if temp_path and os.path.exists(temp_path):
                try:
                    os.remove(
                        temp_path
                    )
                except Exception:
                    pass

            root.after(
                0,
                lambda e=error:
                    finish_error(
                        str(e)
                    )
            )

    threading.Thread(
        target=worker,
        daemon=True
    ).start()



