def lrc_format_timestamp(seconds):
    seconds = max(0.0, float(seconds))
    minutes = int(seconds // 60)
    remain = seconds - (minutes * 60)
    return f"[{minutes:02d}:{remain:05.2f}]"


def lrc_editor_current_track():
    track = current_track()
    if track is None:
        messagebox.showinfo(
            "LRC készítő",
            "Előbb indíts el egy dalt."
        )
        return None
    return track


