    global lrc_editor_window
    global lrc_editor_lines
    global lrc_editor_timestamps
    global lrc_editor_index

    track = lrc_editor_current_track()
    if track is None:
        return

    if lrc_editor_window is not None:
        try:
            if lrc_editor_window.winfo_exists():
                if prefill_text:
                    # Plain lyrics fallback esetén frissen nyitjuk,
                    # hogy biztosan a mostani dalszöveg kerüljön bele.
                    lrc_editor_window.destroy()
                    lrc_editor_window = None
                else:
                    lrc_editor_window.lift()
                    return
        except Exception:
            pass

