nav_buttons = {}


def _nav_style(item, active=False):
    frame = item["frame"]
    icon = item["icon"]
    label = item["label"]

    if active:
        bg = "#0D3152"
        frame.config(
            bg=bg,
            highlightthickness=1,
            highlightbackground=JM_CYAN
        )
        icon.config(
            bg=bg,
            fg=JM_CYAN_BRIGHT
        )
        label.config(
            bg=bg,
            fg=JM_CYAN_BRIGHT
        )
    else:
        bg = JM_PANEL
        frame.config(
            bg=bg,
            highlightthickness=0
        )
        icon.config(
            bg=bg,
            fg=JM_TEXT_2
        )
        label.config(
            bg=bg,
            fg=JM_TEXT_2
        )


def _nav_hover(key, entered):
    item = nav_buttons.get(
        key
    )

    if not item:
        return

    if key == _current_nav_key():
        _nav_style(
            item,
            active=True
        )
        return

    if entered:
        bg = JM_PANEL_2
        item["frame"].config(
            bg=bg,
            highlightthickness=1,
            highlightbackground=JM_BORDER
        )
        item["icon"].config(
            bg=bg,
            fg=JM_CYAN_BRIGHT
        )
        item["label"].config(
            bg=bg,
            fg=JM_TEXT
        )
    else:
        _nav_style(
            item,
            active=False
        )


def nav_button(key, text, command):
    # A régi hívásokból csak a magyar feliratot tartjuk meg.
    label_text = (
        text.split(
            "   ",
            1
        )[-1]
        if "   " in text
        else text
    )

    frame = tk.Frame(
        sidebar,
        bg=JM_PANEL,
        height=42,
        cursor="hand2"
    )
    frame.pack(
        fill="x",
        padx=10,
        pady=2
    )
    frame.pack_propagate(
        False
    )

    install_party_everywhere(
        frame,
        brightness=0.25,
        blur=4.0,
        saturation=0.88
    )

    icon = tk.Label(
        frame,
        text=JM_ICONS.get(
            key,
            "•"
        ),
        font=(
            JM_ICON_FONT_FAMILY,
            16
        ),
        fg=JM_TEXT_2,
        bg=JM_PANEL,
        width=2,
        anchor="center",
        cursor="hand2"
    )
    icon.pack(
        side="left",
        padx=(10, 7)
    )

    label = tk.Label(
        frame,
        text=label_text,
        font=("Segoe UI", 10, "bold"),
        fg=JM_TEXT_2,
        bg=JM_PANEL,
        anchor="w",
        cursor="hand2"
    )
    label.pack(
        side="left",
        fill="both",
        expand=True
    )

    for widget in (
        frame,
        icon,
        label
    ):
        widget.bind(
            "<Button-1>",
            lambda event, c=command:
                c()
        )

        widget.bind(
            "<Enter>",
            lambda event, k=key:
                _nav_hover(
                    k,
                    True
                )
        )

        widget.bind(
            "<Leave>",
            lambda event, k=key:
                _nav_hover(
                    k,
                    False
                )
        )

    item = {
        "frame": frame,
        "icon": icon,
        "label": label,
    }

    nav_buttons[key] = item
    return frame


def _current_nav_key():
    view = str(
        current_view or ""
    )

    if view in {
        "artists",
        "albums_for_artist"
    }:
        return "artists"

    if view in {
        "albums",
        "tracks"
    }:
        return "albums"

    if view == "favorites":
        return "favorites"

    if view in {
        "all_tracks",
        "tracks_all"
    }:
        return "tracks"

    if view.startswith(
        "smart"
    ):
        return "smart"

    if view == "stats":
        return "stats"

    return "home"


def refresh_nav_active():
    active_key = _current_nav_key()

    for key, item in nav_buttons.items():
        try:
            _nav_style(
                item,
                active=(
                    key == active_key
                )
            )
        except Exception:
            pass


