def update_volume_label(value):
    global saved_volume_percent
    global muted
    global pre_mute_volume

    muted = False

    saved_volume_percent = max(
        0.0,
        min(
            100.0,
            float(value)
        )
    )

    pygame.mixer.music.set_volume(
        saved_volume_percent / 100
    )

    volume_value.config(
        text=f"{int(saved_volume_percent)}%"
    )

    try:
        volume_label.config(
            text="🔊"
        )
    except Exception:
        pass

    pre_mute_volume = saved_volume_percent

    schedule_save_settings()


volume.config(
    command=update_volume_label
)

pygame.mixer.music.set_volume(
    saved_volume_percent / 100
)

